"""Consolidação editorial de personagens, com escopo restrito e fontes preservadas."""
from pathlib import Path
import json
import re
import sys
from enciclopedia_comum import ROOT, CONTEUDO, FONTES, escrever, pendencia, fonte, link

def acrescentar_extras():
    """Modo --extras: acrescenta somente o complemento nominal, preservando o núcleo integrado."""
    FONTES['FA']='Fontes/Vault/Vault - Fash Paleskin'
    mp=ROOT/'docs/enciclopedia/personagens.json'
    m=json.loads(mp.read_text(encoding='utf-8'))
    extras=[]
    def ref(c):
        matches=list((CONTEUDO/'Pendencias').glob('*/'+c+' - *.md'))
        assert len(matches)==1,(c,matches)
        return matches[0].relative_to(CONTEUDO).as_posix().removesuffix('.md')
    def cites(t):
        return re.sub(r'@([A-Z]+\d*)',lambda x:fonte(x[1]),t)
    sonho=['PC-002','EV-003','LG-014']
    def E(key,titulo,identidade,percurso,estado,refs,rel,qs,estatuto,aliases=(),campanhas=None):
        destino='Personagens/'+key
        body=cites(identidade)+'\n\n## Trajetória e relações\n\n'+cites(percurso)+'\n\n## Estado e alcance da evidência\n\n'+cites(estado)
        body+='\n\n## Conexões\n\n'+'\n'.join('- '+link(x) for x in rel)
        if qs:
            body+='\n\n## Dúvidas para a sabatina futura\n\n'+'\n'.join('- '+link(ref(x),x) for x in qs)
        body+='\n\n## Fontes consultadas\n\n'+'\n'.join('- '+fonte(x) for x in refs)
        arquivo=escrever(destino,titulo,'personagem',campanhas or ['fash'],body,refs,list(aliases),estatuto=estatuto)
        extras.append({'nome':titulo,'destino':destino,'arquivo':arquivo,'fontes':refs,'pendencias':qs,'extra':True,'estatuto':estatuto,
                       'justificativa':'Complemento nominal solicitado pelo integrador; evidência citada na nota, sem nova identificação material por associação.'})

    E('Filipe Vander','Filipe Vander — contato no sonho',
      'Membro da Torre dos Magos de Lazathar na experiência posteriormente revelada como sonho. Sua existência material não está confirmada. @F (11/09 e 25/10), @J',
      'Recebe o grupo de forma simpática, convence o recepcionista a permitir uma visita à biblioteca e recomenda procurar o Circo por ser mais barato e dispor de informações informais. Enumera Conclave, Taverna, Quartel, Coliseu e Circo, admitindo conhecer pouco sobre as guildas do submundo. Essas são informações do personagem dentro do cenário onírico. @F (11/09).',
      'Não há destino individual depois da revelação nem confirmação de um Filipe correspondente fora do sonho. Não foi convertido em integrante de uma instituição material atual. @F (25/10), @J',
      ['F','J'],['Lugares/Lazathar','Lugares/Plano dos sonhos','Personagens/Fash Paleskin'],sonho,'onirico')
    E('Billy','Billy — guarda do sonho',
      'Guarda e contato da investigação dos corpos com runas no quartel da Lazathar onírica. A reputação de honestidade é informação obtida por Fash no submundo do próprio sonho. @F (20/09 e 25/10), @J',
      'Aceita a carta da Torre dos Magos, mostra os corpos, transcreve runas e pede que o grupo as compreenda antes de espalhar a descoberta. Thorn afirma, sem certeza, que Billy talvez estivesse presente numa autópsia. Depois do desaparecimento do clérigo, Billy organiza buscas e diz conhecê-lo como irmão de armas; suspeita de traição ou manipulação. @F (20/09, 24/09 e 01/10).\n\nAjuda a investigar a sala de Sandro, recolhe documentos comprometedores de juízes, nobres e empresários sem revelar os nomes ao grupo e acompanha a descoberta do corpo mutilado no porto. Sua hipótese inicial de que Sandro pudesse ser vítima não é prova de inocência ou culpa. @F (06/10 e 13/10).',
      'Últimas ações narradas pertencem ao sonho, antes do despertar. Não há pessoa material, cargo atual ou sobrevivência confirmados para Billy nesta continuidade. @F (25/10), @J',
      ['F','J'],['Personagens/Thorn do sonho','Personagens/Sandro','Personagens/Carlos guarda do sonho','Lugares/Lazathar'],sonho,'onirico')
    E('Thorn do sonho','Thorn / Thorne — clérigo do sonho',
      'Clérigo da Igreja do Sol e legista dos corpos marcados no sonho de Lazathar. Thorn e Thorne aparecem para o mesmo interlocutor na sequência do diário; a Igreja do Sol não foi identificada com uma igreja material de Eral. @F (20/09–01/10), @J',
      'Diz ter aberto os corpos pelas costas por ordem de Carlos para preservar a aparência do nobre e evitar favorecimento aparente nas demais vítimas. O grupo confia inicialmente em sua reputação, mas esse julgamento não resolve autoria dos crimes. Ao ir com o grupo ao quartel, oferece chamar Sandro e desaparece. Billy o descreve como antigo irmão de armas. @F (24/09 e 01/10).\n\nA busca agrava a tensão entre igreja e guarda. Uma cabeça arremessada das fileiras da guarda é depois identificada como a de Thorne, desencadeando o confronto. Não se identifica quem o matou nem se provam as hipóteses anteriores de substituição ou encantamento. @F (01/10).',
      'Morte representada pela cabeça decepada dentro da experiência onírica. Isso não confirma a morte de uma pessoa material nem permite fundi-lo a Tólomon ou a outro religioso de Eral. @F (01/10 e 25/10), @J',
      ['F','J'],['Personagens/Billy','Personagens/Carlos guarda do sonho','Personagens/Sandro','Lugares/Plano dos sonhos'],sonho,'onirico',['Thorne do sonho'])
    E('Sandro','Sandro — membro do quartel no sonho',
      'Membro do quartel de Lazathar na investigação onírica, associado a uma sala administrativa, documentos e um familiar que pode se disfarçar. Não há existência material confirmada. @F (01/10–13/10 e 25/10), @J',
      'É ligado ao desaparecimento de Thorn pelo relato das últimas pessoas que o viram. Fash invade sua sala e vê um tapete rubro no teto com mancha negra móvel. Uma figura se passa por Sandro e depois revela ser seu familiar; manda prender o grupo e foge disfarçada. Billy considera possível que o Sandro verdadeiro seja vítima. @F (06/10).\n\nA busca encontra um mapa com caveiras e X e documentos comprometedores que Billy recolhe. Fash interpreta o conjunto como chantagem e autoproteção. O grupo depois encontra Sandro mutilado no porto, considera ser o corpo verdadeiro e segue os pontos do mapa até a câmara ritual. São conclusões e atos narrados nessa camada do sonho. @F (13/10).',
      'Encontrado esquartejado dentro do sonho, sem assassino confirmado e sem desfecho do familiar. Esse destino não atesta morte no mundo material. @F (13/10 e 25/10), @J',
      ['F','J'],['Personagens/Billy','Personagens/Thorn do sonho','Personagens/Fash Paleskin','Lugares/Lazathar'],sonho,'onirico')
    E('Carlos guarda do sonho','Carlos — guarda do sonho de Fash',
      'Guarda citado por Thorn como autor da ordem de realizar autópsias pelas costas na experiência de Lazathar. É referência própria do sonho, distinta tanto de Carlos guarda de Eral quanto de Carlos carpinteiro. @F (24/09 e 25/10), @J',
      'Segundo Thorn, Carlos alegou preservar a aparência de uma vítima nobre e manter o mesmo padrão nos demais casos. A abertura pelas costas atrasou a descoberta de cicatrizes internas; por isso o grupo passa a suspeitar dele e pretende confrontá-lo diante de Billy. A acusação é relato de Thorn e hipótese investigativa, não culpa final demonstrada. @F (20/09 e 24/09).',
      'Não há confronto conclusivo, destino individual ou equivalente material confirmado. Não se transferem a ele a morte e o roubo do corpo do guarda de Eral, nem a possessão do carpinteiro. @F @J',
      ['F','J'],['Personagens/Thorn do sonho','Personagens/Billy','Personagens/Carlos guarda','Personagens/Carlos carpinteiro'],sonho,'onirico')
    E('Roger taverneiro do sonho','Roger — taverneiro anão do sonho',
      'Roger é o anão ligado à grande taverna e à guilda que nela reside em Lazathar. A síntese do handoff o apresenta como Roger taverneiro ou anão; a nota conserva a ligação sem fundi-lo a Roger Cangles. Tudo ocorre no sonho. @F (11/09), @H (Instituições e pessoas do sonho), @J',
      'O atendimento da taverna fornece um mapa mágico, e Roger relata que Teladelion só voltara a crescer depois da chegada do Circo e da derrota da antiga guilda. São informações obtidas dentro da experiência onírica. Um interlocutor do Circo diz que Roger teria sido esquartejado cerca de cinco anos antes, embora aparecesse inteiro e trabalhando; ressurreição é dúvida de Fash, não fato confirmado. @F (11/09).',
      'Presente e ativo na taverna quando encontrado no sonho. O rumor de esquartejamento não fixa morte nem ressurreição, e não há existência material confirmada. @F (11/09 e 25/10), @J',
      ['F','H','J'],['Personagens/Roger Cangles','Lugares/Lazathar','Lugares/Plano dos sonhos'],sonho,'onirico')
    E('Roger Cangles','Roger Cangles — nome da prova da ira',
      'Chefe da guarda que Fash diz conhecer, mencionado por um integrante da guilda durante a prova da porta da ira. Essa informação é parte da experiência onírica; não prova existência ou cargo material. @F (18/08 e 25/10), @J',
      'Na cena que parece mostrar o passado, Fash reconhece a bolsa do pai entre membros da guilda comemorando. Um deles confessa que o serviço mandava matar todos exceto a criança e aponta Roger Cangles como contato que repassava ordens. Trata-se de confissão dentro de teste onírico, não comprovação histórica independente da morte dos pais. @F (18/08).',
      'Sem encontro conclusivo ou destino posterior recuperados. Não se confunde com Roger anão/taverneiro e não foi declarado culpado por crime material a partir da prova. @F @J',
      ['F','J'],['Personagens/Roger taverneiro do sonho','Personagens/Fash Paleskin','Personagens/Mendrik Daergel','Personagens/Felbira Daergel'],sonho,'onirico')
    E('Taruk','Taruk — líder relatado no sonho',
      'Líder goblinoide mencionado por um interlocutor do Circo no sonho de Lazathar, sem encontro direto narrado. O nome não foi identificado com Tork, chefe goblin atual ou outra figura por semelhança. @F (11/09), @J',
      'O interlocutor afirma que uniu e organizou goblinoides, expulsando bárbaros que buscaram refúgio na capital. Também transmite rumor de sua morte e observa que os goblins continuam organizados. Fash pergunta se outro líder assumiu; a fonte não responde. São notícia e rumor dentro do sonho. @F (11/09).',
      'Morte incerta mesmo dentro da narrativa onírica. Não há biografia material, sucessão ou atividade atual confirmadas. @F (11/09 e 25/10), @J',
      ['F','J'],['Lugares/Lazathar','Lugares/Plano dos sonhos','Personagens/Fash Paleskin'],sonho,'onirico')
    E('Mendrik Daergel','Mendrik Daergel — background de Tinkar',
      'Comerciante gnomo e pai de Tinkar/Fash no background anexo ao diário antigo, casado com Felbira. A continuidade material desse background, incluindo Eldrosia, permanece a confirmar; não se apresenta Mendrik como pessoa material atestada. @F (BACKGROUND), @FA @J',
      'O texto diz que o casal negociava minerais e metais de Thal Karak, ensinando inventário, rotas e negociação ao filho. Ambos são mortos numa emboscada comercial ao norte; Tinkar ficara em casa com febre. A ligação com a Lâmina da Meia-Noite é conclusão do filho. A prova da ira dramatiza uma confissão sobre o serviço, mas o sonho não valida sozinho a autoria real. @F (BACKGROUND e 18/08).',
      'Morto segundo o background, com estatuto de continuidade pendente. Nome, vínculo familiar e destino textual são preservados sem canonizar mundo ou responsáveis pelo assassinato. @F @FA @J',
      ['F','FA','J'],['Personagens/Felbira Daergel','Personagens/Fash Paleskin','Personagens/Jorven','Personagens/Roger Cangles'],sonho,'background_continuidade_pendente')
    E('Felbira Daergel','Felbira Daergel — background de Tinkar',
      'Comerciante gnoma e mãe de Tinkar/Fash no background anexo ao diário antigo, casada com Mendrik. Sua identidade é documentada nesse texto; a existência material nessa continuidade ainda depende de conciliação com o sonho. @F (BACKGROUND), @FA @J',
      'O casal mantém comércio respeitado de metais e minerais de Thal Karak e cria o filho nesse trabalho. A narrativa relata a morte de ambos em uma viagem comercial, com carga saqueada e registros destruídos. A suspeita sobre a Lâmina da Meia-Noite é a leitura de Tinkar; não há ordem material confirmada por fonte independente. @F (BACKGROUND).',
      'Morta segundo o background. Não se inventam profissão separada, atos individuais na emboscada ou causa diversa da registrada, e não se resolve sua continuidade por associação com a prova da ira. @F @J',
      ['F','FA','J'],['Personagens/Mendrik Daergel','Personagens/Fash Paleskin','Personagens/Roger Cangles'],sonho,'background_continuidade_pendente')
    E('Rask','Rask — cobrador do background de Fash',
      'Humano descrito como brutamontes que acompanha Tinkar numa cobrança da Lâmina da Meia-Noite, na cena HOJE do background. O gancho e os nomes dessa camada aguardam revisão de continuidade material. @F (BACKGROUND/HOJE), @FA @J',
      'Lembra a ordem de quebrar o tornozelo de Jorven caso o ferreiro não pague três semanas de contribuição. Quando avança, Tinkar o contém com a mão no ombro e tenta conversar. O texto não narra uma agressão consumada por Rask nessa cena. @F (HOJE).',
      'A cena termina com frio e névoa percebidos por Tinkar, sem destino próprio para Rask. Não foi identificado com qualquer guarda ou cobrador material posterior. @F @J',
      ['F','FA','J'],['Personagens/Jorven','Personagens/Fash Paleskin','Lugares/Plano dos sonhos'],sonho,'background_continuidade_pendente')
    E('Jorven','Jorven — ferreiro do background de Fash',
      'Ferreiro de bigode chamuscado e mãos calejadas, citado no background de Tinkar/Fash. Tinkar lembra que negociara com Mendrik e lhe dava doces na infância. A continuidade material dessa história permanece pendente. @F (HOJE), @FA @J',
      'Deve três semanas de contribuição à guilda e afirma não ter encomendas suficientes. Sua oficina tem ferramentas velhas, nenhum aprendiz e uma marca quase apagada da Lâmina da Meia-Noite. Tinkar interpreta a marca como vigilância ou proteção, sem saber a razão, e impede Rask de avançar antes de sentir o frio e a névoa. @F (HOJE).',
      'A cena é interrompida antes de esclarecer a marca ou a cobrança. A antiga oficina reaparece na prova da ira, mas isso não atesta que o ferreiro fosse cúmplice material da morte dos pais. @F (HOJE e 18/08), @J',
      ['F','FA','J'],['Personagens/Rask','Personagens/Fash Paleskin','Personagens/Mendrik Daergel'],sonho,'background_continuidade_pendente')
    E('Pai de Glim','Pai de Glim e Lilo',
      'Pai de Glim e Lilo, sem nome recuperado. O background o liga ao trabalho com madeira e resina e descreve a rotina trabalhadora dos pais pela perspectiva dos filhos. Esse background foi aprovado como cânone observado seu ponto de vista. @B (ato 1), @J',
      'Quando Glim retorna sem Lilo, pergunta pelo irmão, segura seu braço e manda que fique em casa. Glim depois o distrai para recuperar o grimório e fugir. Não há diálogo de perdão ou encontro posterior com o pai. @B (ato 1, parte II).\n\nNo retorno à aldeia, Nina informa que ele morreu nos Doze Dias depois de ir com outros ao cemitério e não voltar. O relato é notícia de Nina, sem testemunho da morte ou causa precisa. Glim recupera uma fivela simples do cinto como memória do pai. @B (ato 6).',
      'Morto segundo a última notícia familiar narrada por Nina. Nome, circunstâncias no cemitério e destino do corpo não recuperados; a fivela não tem poder mágico demonstrado. @B (ato 6).',
      ['B','J'],['Personagens/Glim Sombrasselva','Personagens/Lilo Sombrasselva','Personagens/Mae de Glim','Personagens/Nina','Itens/Memorias materiais de Glim'],['PC-042'],'material_com_perspectiva',campanhas=['glim'])
    E('Mae de Glim','Mãe de Glim e Lilo',
      'Mãe de Glim e Lilo, sem nome recuperado. Sua história é conservada sob as perspectivas narrativas do background, aprovado pelo jogador. Não há diagnóstico clínico ou identidade além do vínculo familiar. @B (ato 1), @J',
      'Ao perceber que Glim voltou sem Lilo, reage à perda com choro, invoca o nome do filho e diz a Glim que preferia que ele tivesse morrido. A lembrança estrutura a culpa e a fuga de Glim; não foi transformada numa opinião permanente da mãe por inferência. @B (ato 1, parte II).\n\nAnos depois, Nina diz que continua viva, sem se recuperar mentalmente e cuidada por outras pessoas. A esperança de que desejasse o retorno do filho é tentativa de Nina, que admite não falar por ela. Glim recolhe um pente quebrado como memorial. @B (ato 6).',
      'Viva e incapacitada na última notícia de Nina; estado posterior e responsáveis pelo cuidado desconhecidos. Não se afirma morte, cura ou perdão sem encontro documentado. @B (ato 6).',
      ['B','J'],['Personagens/Glim Sombrasselva','Personagens/Lilo Sombrasselva','Personagens/Pai de Glim','Personagens/Nina','Itens/Memorias materiais de Glim'],['PC-042'],'material_com_perspectiva',campanhas=['glim'])
    E('Lamassu','Lamassu ligado a Tauro',
      'Criatura sem nome pessoal, de cabeça leonina e asas, identificada como Lamassu por Arkhavel a partir da descrição do agressor de Tauro. A classificação de bondade e a hipótese de ter atacado por tomar o minotauro como mau são explicações de Arkhavel, não motivo confessado pelo ser. @G (S3).',
      'Tauro, a mulher do braço e Glim o encontram fora de Eral. O Lamassu tampouco sabe explicar a transformação do braço. Ouve que Tauro é um golem com item de consciência, julga a criação profana e usa detecção de mal e remoção de maldição. A mulher não muda, enquanto Tauro se contorce e depois se recupera. @G (S3).\n\nAfirma que várias almas estão presas em Tauro, defende sua destruição para libertá-las e adverte que libertar a última encerrará sua existência. Glim argumenta por buscar outro método; o Lamassu promete consultar alguém mais informado. As afirmações sobre a alma em agonia e o desfecho necessário pertencem ao diagnóstico dele. @G (S3).',
      'Parte para buscar informações. Não há retorno resolutivo registrado; Tauro decide permanecer em Eral à espera. Não foi demonstrado que o Lamassu conhecia Arkhavel como criador. @G (S3–S4).',
      ['G'],['Personagens/Tauro','Personagens/Mulher originada do braco','Personagens/Arkhavel','Personagens/Glim Sombrasselva'],['PC-018'],'material_em_cena',campanhas=['glim'])
    E('Aboleth da mansao','Aboleth da mansão do prefeito',
      'Aboleth sem nome pessoal recuperado, escondido na casa do prefeito de Eral. T16 o distingue do filho de Arkhavel e confirma que era seu parceiro secreto, desconhecido de Silthan e do Mercado Negro. @T16 (01:18:44–01:18:57).',
      'Depois do combate ao prefeito e ao mordomo Kuat, Glim encontra a sala com lago e teme a presença do Aboleth. Quando Arkhavel resgata o grupo, Okay lhe conta a suspeita; o artificer entra, volta e o diário registra que matou a criatura e tomou o tesouro. O grupo não acompanha a luta em detalhe. @G (S12).\n\nO prefeito humano estava controlado; o mestre explica a distinção entre o homem e o filho chamado prefeito nas cartas. Isso não individualiza qual poder produziu cada etapa do domínio nem faz de Donovan o parceiro presente. @T16 (01:17:32–01:18:57).',
      'Morto por Arkhavel segundo o diário; nome, história anterior e termos da parceria não recuperados. A morte não fornece resposta automática sobre a identidade e o destino do filho de Arkhavel. @G @T16',
      ['G','T16'],['Personagens/Filho de Arkhavel ligado ao prefeito','Personagens/Donovan','Personagens/Kuat','Personagens/Prefeito humano de Eral','Personagens/Arkhavel'],['PC-016','PC-017'],'material_relato_de_desfecho',campanhas=['glim'])
    E('Lirista espectral','Lirista espectral da viagem de volta',
      'Morto-vivo musical sem nome pessoal, encontrado durante o retorno da busca dos rangers. Aparece como mulher de cabelos rosados, roupas vegetais e harpa dourada; os traços parecem misturar espécies. O mestre confirma que usa alteração de aparência, portanto a imagem não determina sua espécie em vida. @T18 (00:22:57–00:25:45; 00:59:08–01:01:28).',
      'Atrai os viajantes com música, fascínio e sugestões e tenta roubar Carisma por toque. Após a fuga, o conhecimento de Okay permite identificá-lo como lirista espectral. O mestre explica que fora um ser maligno ligado à música, sem fixar que fosse necessariamente bardo ou sátiro. @T18 (00:58:39–01:01:28).',
      'O grupo escapa; não há morte da criatura confirmada nem retorno posterior. Não é uma dríade identificada e não foi fundida à portadora do cajado de girassol. A identidade anterior não é necessária para resolver a viagem já narrada e não gerou pergunta nova. @G (S18), @T18',
      ['T18','G'],['Eventos/Busca dos rangers','Personagens/Okay dBoa','Personagens/Driade do cajado de girassol'],[],'material_em_cena',campanhas=['glim'])
    E('Mulher da Lua Sangrenta','Mulher da Lua Sangrenta',
      'Mulher sem nome recuperado, lembrada por Okay como contato da Lua Sangrenta. A Lua Sangrenta é a organização dos que enfrentaram a Noite Eterna, conforme correção explícita do mestre; não é o próprio fenômeno. @T25 (01:43:16–01:43:25), @T24 (01:20:08–01:21:53).',
      'Na conversa sobre Firael e os corpos, Okay associa a organização interessada em obter conhecimentos ao aviso dessa mulher. O mestre recorda que antes se pensava em vampiros. A síntese do handoff registra o alerta sobre corpos e conhecimentos roubados; a consulta atual não recupera a cena original de seu encontro. @T25 (01:42:37–01:43:25), @H (Arquivistas, Lua Sangrenta e Zodíacos).',
      'Contato anterior atestado por lembrança da mesa, com nome, cargo, localização e atividade atuais desconhecidos. Não foi identificada como mulher das memórias, bruxa ou mulher do hidromel, nem teve filiação formal inventada além da associação expressa no relato. @T25 @H',
      ['T25','T24','H'],['Faccoes/Lua Sangrenta','Personagens/Okay dBoa','Personagens/Firael','Eventos/Noite Eterna'],['FC-014'],'contato_recordado',campanhas=['glim'])

    destinos={x['destino'] for x in extras}
    m['notas']=[n for n in m['notas'] if n['destino'] not in destinos]+extras
    m['extras']=[n for n in m.get('extras',[]) if n['destino'] not in destinos]+extras
    m['cobertura'].update(extras=len(m['extras']),total_notas=len(m['notas']))
    m['limites']=[x for x in m['limites'] if not x.startswith('Tareksin, pais de Glim')]
    limite='O complemento nominal acrescenta 18 notas; figuras do sonho e do background antigo conservam estatuto onírico ou continuidade pendente. Tareksin, anjos e emissário de Hextor ainda não têm notas próprias neste domínio.'
    if limite not in m['limites']:m['limites'].append(limite)
    adicionais={
      FONTES['F']:' Complemento: leitura direta de 11/09, 20/09, 24/09, 01/10, 06/10, 13/10, prova da ira de 18/08 e BACKGROUND/HOJE para personagens do sonho e família Daergel.',
      FONTES['G']:' Complemento: leitura direta de S3–S4 para encontro e diagnóstico do Lamassu, S12 para Aboleth e S18 para identificação e fuga do lirista.',
      FONTES['T18']:' Complemento: 00:22–00:25 e 00:58–01:01 sobre aparência, habilidades, identificação e história não individualizada do lirista.',
      FONTES['T25']:' Complemento: 01:42–01:43 sobre lembrança da mulher da Lua Sangrenta e boatos anteriores de vampiros.',
      FONTES['T24']:' Complemento: 01:20–01:21 sobre Lua Sangrenta como organização distinta da Noite Eterna.'}
    for f in m['fontes_realmente_consultadas']:
        if f['destino'] in adicionais and adicionais[f['destino']].strip() not in f['alcance']:
            f['alcance']+=adicionais[f['destino']]
    for x in extras:
        p='conteudo/'+x['arquivo']
        if p not in m['escritas']:m['escritas'].append(p)
    m['estado']='congelado'
    mp.write_text(json.dumps(m,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    print(json.dumps({'extras_acrescentados':len(extras),'notas_totais':len(m['notas']),'pendencias_pc':len(m['pendencias'])},ensure_ascii=False))

if '--extras' in sys.argv:
    acrescentar_extras()
    raise SystemExit

T = {n: f'Fontes/Transcricoes/Glim - Sessao {n:02d} - {d}' for n,d in {
    13:'2026-05-27',14:'2026-06-17',16:'2026-08-05',17:'2026-08-17',18:'2026-08-25',
    20:'2026-09-02',21:'2026-09-13',22:'2026-09-16',23:'2026-09-27',24:'2026-09-30',
    25:'2026-10-05',26:'2026-10-20'}.items()}
FONTES.update({f'T{n}':p for n,p in T.items()})
FONTES['FA']='Fontes/Vault/Vault - Fash Paleskin'
registro=json.loads((ROOT/'docs/enciclopedia/registro-entidades.json').read_text(encoding='utf-8-sig'))['entidades']
cadastro={e['destino']:e for e in registro if e['dominio']=='personagens'}
notas=[]
perguntas=[]
qp={}

def cita(texto):
    return re.sub(r'@([A-Z]+\d*)',lambda m:fonte(m[1]),texto)

def Q(num,titulo,pergunta,contexto,refs,nomes,prioridade='media',natureza='lacuna'):
    codigo=f'PC-{num:03d}'
    destinos=[x if '/' in x else 'Personagens/'+x for x in nomes]
    p=pendencia(codigo,titulo,'Personagens',['fash','glim'],pergunta,cita(contexto),refs,destinos,prioridade,natureza)
    qp[num]=p
    perguntas.append({'id':codigo,'destino':p,'titulo':titulo,'prioridade':prioridade,'entidades':destinos})

def N(key,identidade,percurso,estado,refs,rel=(),qs=(),aliases=(),campanhas=None,titulo=None):
    destino='Personagens/'+key
    if destino not in cadastro:
        assert titulo, 'Extra precisa de título explícito'
    nome=titulo or cadastro[destino]['nome']
    texto=cita(identidade)+'\n\n## Trajetória e relações\n\n'+cita(percurso)+'\n\n## Estado mais recente\n\n'+cita(estado)
    if rel:
        texto+='\n\n## Conexões\n\n'+'\n'.join('- '+link(x) for x in rel)
    if qs:
        texto+='\n\n## Dúvidas para a sabatina futura\n\n'+'\n'.join('- '+link(qp[q],f'PC-{q:03d} — '+next(x['titulo'] for x in perguntas if x['id']==f'PC-{q:03d}')) for q in qs)
    texto+='\n\n## Fontes consultadas\n\n'+'\n'.join('- '+fonte(x) for x in refs)
    p=escrever(destino,nome,'personagem',campanhas or ['fash','glim'],texto,refs,list(aliases))
    notas.append({'nome':nome,'destino':destino,'arquivo':p,'fontes':refs,'pendencias':[f'PC-{q:03d}' for q in qs], 'extra':destino not in cadastro})

Q(1,'Fash no presente','Fash está vivo na época da sessão 26? Onde está, em que condição e ainda exerce pessoalmente a liderança do Ébano?',
  'A fundação do Ébano por Fash é confirmação do jogador que atribui a informação ao mestre. Sua sobrevivência atual é crença sem certeza; as especulações em off de S25 não estabelecem localização ou comando. @J @T25', ['J','T25'],['Fash Paleskin','Faccoes/Ebano'],'alta')
Q(2,'Continuidade de Tinkar e passado de Fash','Quais elementos do background de Tinkar Daergel são materiais e quais pertencem ao sonho? Mendrik, Felbira, Jorven, Rask, a Lâmina da Meia-Noite e a morte dos pais permanecem canônicos nessa continuidade?',
  'O arquivo de Fash associa os nomes e Eldrosia ao background; a revelação do diário e a errata posterior exigem separar sonho de mundo material. Não há resposta individual para essas pessoas. @FA @F @J',['FA','F','J'],['Fash Paleskin'],'alta','continuidade')
Q(3,'Ascendência de Okay','Okay é elfo cinza ou meio-elfo de ascendência humana e elfa cinzenta? Qual descrição deve orientar a nota e a ficha atuais?',
  'Glim o apresenta como elfo cinza na caravana; o dossiê o define como meio-elfo. A divergência não é resolvida apenas pela descrição visual de Glim. @G @OK',['G','OK'],['Okay dBoa'],'media','divergencia')
Q(4,'Memórias e vidas de Okay','Quais lembranças anteriores a Kael Okay já recuperou, quais ainda dependem da mulher da montanha e qual é a ligação pessoal confirmada de suas encarnações com os Zodíacos?',
  'Em S25 o mestre recupera a última vida, mas exclui memórias de vidas anteriores que Kael havia recuperado. A tradição e os artefatos zodiacais não demonstram que Okay conheça toda a organização. @T25',['T25'],['Okay dBoa','Kael','Mulher das memorias','Faccoes/Zodiacos'],'alta')
Q(5,'Timo entre morte planta e cajado','Como Timo morreu e se tornou planta? Quanto de sua consciência persiste no cajado de girassol, e quem é a dríade que o porta?',
  'O jogador confirma Timo como o druida/planta/cajado; S25 confirma o artefato na mão da dríade. Isso não identifica a dríade como Timo e não descreve a transformação nem sua vontade atual. @J @T25',['J','T25'],['Timo','Driade do cajado de girassol','Itens/Cajado de girassol'],'alta')
Q(6,'Timo Pé-de-Musgo Fesh e versões antigas','O Resumo detalhado de Timo Pé-de-Musgo descreve esta mesma campanha? Fesh corresponde a Fash, e quais nomes, ações e datas desse resumo podem ser integrados?',
  'A fonte derivada usa Timo Pé-de-Musgo, Fesh e datas 530/536; a narrativa se aproxima do diário de Fash, mas não prova equivalência de todas as variantes. Nenhum alias Fesh foi aplicado. @TIM @F',['TIM','F'],['Timo','Fash Paleskin'],'alta','continuidade')
Q(7,'Firael e o reconhecimento de Okay','Firael sabe que Okay é a reencarnação de Kael? Por que enviou mapas que mobilizam o grupo contra interesses do Mercado Negro, seu aliado?',
  'O mestre confirma autoria dos pergaminhos pela letra, liderança atual e subordinação ao Cérebro. Motivos como vingança do dragão e consumo de cérebros são hipóteses, e o reconhecimento de Okay é explicitamente desconhecido. @T25',['T25'],['Firael','Okay dBoa','Itens/Mapas e pergaminhos de Firael'],'alta')
Q(8,'Condição pessoal do Cérebro','O Cérebro Ancião foi materialmente libertado? Quando e por quem, e onde está seu corpo ou manifestação atual?',
  'O diário registra degradação das runas e doze derrotas de Firael, mas não documenta uma libertação inequívoca. S25 o coloca acima de Firael sem resolver o estado físico. @F @T25',['F','T25'],['Cerebro Anciao','Firael'],'alta')
Q(9,'Responsabilidade pelas mortes de Lilo e Piche','Qual foi o agente ou causa do ataque a Lilo e Piche e o que Glim já sabe sobre a responsabilidade pelas mortes? Há confirmação de alguma relação pessoal entre a sombra que atacou e Fash ou agentes do Ébano?',
  'O background é canônico sob perspectiva de Glim. A ruptura e as mortes são narradas; a motivação da sombra não é explicada e a culpa sentida por Glim não demonstra intenção sua. A associação com Ébano é interpretação de Glim. A origem do livro e o mecanismo do selo são tratados em [[Pendencias/Itens/IT-001 - Entidade e selo do grimório|IT-001 — Entidade e selo do grimório]]. @B @J',['B','J'],['Glim Sombrasselva','Lilo Sombrasselva','Piche','Itens/Grimorio de Glim'],'alta')
Q(10,'Identidade da sombra de Lilo','O familiar que saiu do grimório contém a alma ou lembranças do Lilo original? O que sabe de sua morte, que autonomia tem e quais visões de Lilo eram manipulações?',
  'S24 confirma a forma do irmão e a função de familiar após o sacrifício da sombra de Crave. A narração não confirma ressurreição nem identidade espiritual completa; visões anteriores foram explicitamente problematizadas. @T24 @H',['T24','H'],['Lilo Sombrasselva','Glim Sombrasselva','Crave'],'alta')
Q(11,'Memória juvenil da runa e destino de Piche','Quando e onde Glim viu a runa perfeita do deus da morte na juventude? Isso se relaciona ao grimório ou às mortes de Lilo e Piche, e o corpo de Piche tem alguma condição sobrenatural confirmada?',
  'S21 recupera aperto no peito diante de uma runa conhecida, sem desenvolver o episódio no background. Piche é conservado por Glim como vínculo afetivo, sem ressurreição demonstrada. @T21 @B',['T21','B'],['Glim Sombrasselva','Piche','Lilo Sombrasselva'],'media')
Q(12,'Crave após as provações','A redenção de Crave perante Kord foi concluída ou continua pendente? Quais são os efeitos permanentes da perda da sombra e da relação atual com o amuleto?',
  'O massacre motivou a busca por redenção; o rito do cinto e a manifestação de Lilo produziram consequências distintas. A advertência de Tariun em S25 não é desfecho de sua fé. @T23 @T24 @T25',['T23','T24','T25'],['Crave','Kord','Itens/Amuleto de Kord'],'alta')
Q(13,'Rudiger e a figura do prelúdio','Rudiger Quebra-Ferro era Kord, avatar, emissário ou outra pessoa? É a mesma figura que recolhe o sacerdote vivo na neve, e qual foi seu destino após deixar Crave?',
  'Tólomon apresenta a identificação com Kord como hipótese. S23 mostra a figura do prelúdio, mas aparência e reverência não bastam para fixar sua natureza. @G @T23',['G','T23'],['Rudiger','Kord','Crave'],'alta')
Q(14,'Ryld luz e inspeção','Qual a origem confirmada da luz de Ryld, e o que ele descobriu ao inspecionar o posto dos Mind Shredders? Onde e em que trabalho ficou ao se separar do grupo?',
  'Pelor é hipótese de Tólomon. A síntese do handoff registra a incumbência da inspeção, sem resultado. S20 ainda distingue os contratos planares e a coleta de escaravelhos. @G @H @T20',['G','H','T20'],['Ryld','Pelor'],'alta')
Q(15,'Arkhavel e retorno','Quais filhos Arkhavel saiu para procurar, o que sabe do envolvimento deles em Eral e quando ou sob que condição voltará à torre?',
  'S16 menciona a ausência por busca dos filhos. As cartas atribuem indiferença a Arkhavel, mas essa é uma avaliação dos adversários, não descrição onisciente de suas intenções. @T16',['T16'],['Arkhavel','Donovan','Filho de Arkhavel ligado ao prefeito'],'alta')
Q(16,'Kuat filho e destino do interrogado','O Kuat que se disfarçava de mordomo é precisamente o filho de Arkhavel chamado de prefeito nas cartas? Qual seu nome pessoal e qual foi seu destino após a captura e o interrogatório?',
  'Glim registra a captura do Kuat em S12. O dossiê de Okay registra confirmação na mesa de análise e interrogatório posterior; T16 distingue o filho, o prefeito humano e Donovan, mas não fornece aqui uma identificação nominal inequívoca de todos os rótulos. @G @OK @T16',['G','OK','T16'],['Kuat','Filho de Arkhavel ligado ao prefeito','Prefeito humano de Eral','Donovan'],'alta')
Q(17,'Donovan','Qual é a natureza da filiação de Donovan a Arkhavel, onde ele está e qual função exerce perante o Mercado Negro? As avaliações nas cartas são dele ou atribuições de terceiros?',
  'S16 o apresenta como outro filho, conhecido e temido ou respeitado pelo Mercado, sem fixar endereço ou cargo. Não é seguro fundi-lo ao filho presente em Eral. @T16',['T16'],['Donovan','Arkhavel'],'alta')
Q(18,'Tauro suas almas e Lamassu','As almas dos 32 ajudantes continuam presas em Tauro? O Lamassu voltou com informações, e como Tauro ficou após os ferimentos na defesa da torre e a morte da mulher?',
  'A análise de S2 revela a construção; a investigação das almas pelo Lamassu está resumida no handoff. S18 confirma Tauro vivo, gravemente ferido, ao lado da jovem morta. @G @H @T18',['G','H','T18'],['Tauro','Mulher originada do braco','Arkhavel'],'alta')
Q(19,'Identidade da mulher do braço','Qual é o nome e a origem própria da mulher surgida do braço de Tauro? De onde veio seu coração de warforged e o que aconteceu com seu corpo e sua alma após o ataque?',
  'Arkhavel não explica sua formação em S2; retirar o coração a mataria. S18 confirma a menina morta na torre. Não se trata da mulher possuída trazida pela caravana. @G @T18',['G','T18'],['Mulher originada do braco','Tauro'],'media')
Q(20,'Mulher possuída da caravana','Quem era a mulher trazida sob escolta a Arkhavel, qual ritual causou a possessão e qual foi o resultado do tratamento? Há parentesco confirmado com os Talent?',
  'Arkhavel relata um ritual malfeito e possessão; o parentesco foi conjectura do grupo pela escolta e pelo pagamento em esmeralda. @G',['G'],['Mulher possuida da caravana','Teodoron Talent','Arkhavel'],'media')
Q(21,'Morte e família de Carlos carpinteiro','Quando, como e por quem Carlos carpinteiro morreu antes de seu corpo ser usado por Vesperal? Qual o estado atual de sua esposa e dos dois filhos após a magia viva e o ataque a Eral?',
  'O jogador identifica o carpinteiro como corpo da S26. As cenas anteriores o mostram trabalhando e com família; o intervalo até a morte não está explicado. Cleide foi improviso de Glim, sem nome confirmado. @J @G @T26 @H',['J','G','T26','H'],['Carlos carpinteiro','Aurel Vesperal'],'alta')
Q(22,'Cadáver de Carlos guarda','Quem roubou o cadáver de Carlos guarda da igreja e qual foi seu destino? Há prova de relação com a organização de Firael ou somente suspeita?',
  'A síntese do handoff do caso S8–S11 distingue esse corpo do carpinteiro. O roubo não permite atribuir automaticamente autoria ao grupo de Firael. @H @J',['H','J'],['Carlos guarda','Firael'],'media')
Q(23,'Vesperal e a encomenda','Qual é a identidade e natureza original de Aurel Vesperal? O possessor sobreviveu à destruição do corpo, quem foi a mulher do hidromel e qual é a ligação confirmada com os anjos caçadores?',
  'S26 confirma corpo de Carlos, sangue coagulado, drenagem e a encomenda posterior por mulher não vista. A associação ao demônio procurado é inferência do grupo apoiada pela lembrança de um sobrenome semelhante; lich não foi confirmado. @T26 @J',['T26','J'],['Aurel Vesperal','Carlos carpinteiro','Itens/Pergaminho do anjo'],'alta')
Q(24,'Taverneira nome e comunicação','Qual era o nome da taverneira contratante de Eral? Como sua morte foi conhecida por Okay e Crave, e Glim já recebeu essa notícia depois da sessão 26?',
  'A síntese do handoff registra morte comunicada privadamente e diferença de conhecimento entre personagens. Não há nome recuperado; nomes incertos na transcrição não foram promovidos. @H',['H'],['Taverneira de Eral','Glim Sombrasselva','Crave','Okay dBoa'],'media')
Q(25,'Destino de Tólomon','Tólomon morreu no ataque a Eral ou está entre os sobreviventes? Quem pode confirmar seu destino individual e seu último ato conhecido?',
  'S18 confirma morte dos clérigos combatentes e sobrevivência de sacerdotes que não lutaram, mas a fala com nomes reconhecidos de modo incerto não resolve o destino pessoal de Tólomon. @T18 @H',['T18','H'],['Tolomon'],'alta')
Q(26,'Rangers desaparecidos','O que aconteceu com Folha-Seca, Hanta e os demais da expedição contra os guardas? Que notícia ou testemunha confirma o paradeiro de cada um?',
  'Ao voltar, o grupo não encontra rangers ou druidas. Glim teme que todos morreram, mas o mestre não confirma mortes. A amiga de Folha-Seca havia desaparecido antes e é outro caso. @T18 @H',['T18','H'],['Folha-Seca','Hanta'],'alta')
Q(27,'Amiga de Folha-Seca','Quem era a amiga desaparecida de Folha-Seca e o que se sabe de seu sumiço anterior à missão contra os guardas?',
  'A síntese do handoff identifica o sumiço anterior e sem nome recuperado; não deve ser fundido à expedição desaparecida depois. @H',['H'],['Folha-Seca'],'media')
Q(28,'Silthan e os proprietários','Silthan sobreviveu à queda da arena? Qual era sua relação pessoal com o conde e a condessa apontados como donos e com os chefes combatidos no local?',
  'S13 lista doze financiadores e um casal como donos; a síntese do handoff registra Silthan como dono ou líder, tributos, coação pelo filho de Arkhavel e morte de seu irmão. Essas funções não são automaticamente equivalentes. @T13 @H',['T13','H'],['Silthan'],'media')
Q(29,'Kenku caolho','Qual é o nome correto do Kenku caolho e onde ficou após a traição? Qual participação individual teve no plano e no ataque a Tork e aos clérigos?',
  'A síntese do handoff conserva Tausky/Talosky/Towski como variantes. S18 confirma a traição coletiva, mas não identifica cada agressor ou o destino pessoal do interlocutor. @H @T18',['H','T18'],['Kenku caolho','Tork'],'alta')
Q(30,'Tariun e a tarefa da montanha','Tariun concluiu a tarefa que foi terminar na montanha? Qual foi o resultado para os sobreviventes e qual a fonte ou condição da advertência sobre Glim e Okay?',
  'A síntese do handoff da S25 registra sua partida e o aviso de que Crave teria de escolher, sem desfecho. O aviso não prova um futuro inevitável. @H',['H'],['Tariun','Crave','Glim Sombrasselva','Okay dBoa'],'alta')
Q(31,'Colegas de Okay e mestre desaparecido','Qual o nome do antigo mestre de Okay levado na segunda expedição, e que notícias novas Tahen e Elrohir têm sobre ele e os demais desaparecidos?',
  'S24 confirma mestre na segunda leva para o covil marítimo; a síntese do handoff distingue os colegas e esse destino do território antigo do dragão negro. @T24 @H',['T24','H'],['Tahen','Elrohir','Okay dBoa'],'media')
Q(32,'Bruxas sobreviventes e Elena','Quais das três bruxas sobreviveram, qual provocou a Noite Eterna e onde está Elena após a destruição do artefato? Elena Tanziam e Serethyn são nomes de quem, e qual relato sobre sua natureza é verdadeiro?',
  'O diário opõe o relato pessoal de Elena ao livro das bruxas; o sacrifício de uma irmã é hipótese de Elena. A confirmação da bruxa como causa da Noite Eterna não individualiza cada etapa. @F @J',['F','J'],['Morvessh','Selara','Lyvessa','Elena'],'alta')
Q(33,'Grixxian e a camada do sonho','Grixxian existe fora do sonho? Qual sua relação real com Elena e as bruxas e qual foi seu destino após o despertar?',
  'O demônio de cinzas aparece no sonho e é depois relacionado às bruxas; hierarquia e derrotas oníricas não demonstram morte material. @F @H',['F','H'],['Grixxian','Elena','Morvessh'],'media')
Q(34,'Necromante Lídia e Cavaleiro','Qual foi o destino pessoal do Necromante e de Lídia? O Cavaleiro da Morte despertou e, se sim, agiu contra eles ou tomou a necrópole?',
  'O diário registra a ameaça e perda de vínculo perto da passagem. O jogador apresenta despertar e tomada da necrópole apenas como hipótese condicional. A nomenclatura formal da organização é tratada no domínio de facções. @F @J',['F','J'],['Necromante','Lidia','Cavaleiro da Morte'],'alta')
Q(35,'Anão guardião real e família','Qual o nome do anão guardião/ferreiro da campanha material e qual foi seu destino e o de sua família após a morte do Druida Sangrento? Ele é distinto do anão das provas oníricas?',
  'O diário descreve coação pela família escravizada e disfarce do drow. O anão das sete portas aparece na camada declarada sonho; não foi fundido ao guardião material. @F @J',['F','J'],['Anao guardiao','Druida Sangrento'],'media')
Q(36,'Dragão negro no presente','O dragão negro que matou Kael continua vivo e no mesmo território na época da campanha atual? Qual é seu nome e que acordo mantém com Firael?',
  'S25 confirma a morte de Kael e o acordo antigo, enquanto os mapas descrevem forças locais. Não há nesta consulta um encontro atual com o próprio dragão. @T25 @H',['T25','H'],['Dragao negro','Kael','Firael'],'alta')
Q(37,'Hourian Haurim e revoada','Hourian e Haurim designam o mesmo dragão? Qual a grafia confirmada, quais relatos de sua vida são históricos e qual revoada o matou?',
  'O diário traz Hourian no relato de Firael e Covis de Haurim como destino. A revoada de sua morte não foi demonstrada como a Revoada Branca. Nomes expandidos do documento em revisão não foram adotados. @F @PH',['F','PH'],['Hourian Haurim'],'media')
Q(38,'Cogu e Rake','Qual foi o destino de Cogu e da matilha depois da campanha antiga? Há legado ou consequência específica da morte de Rake além da escolha de Timo por Silvanus?',
  'O diário confirma Rake morto e Cogu ainda protegido na floresta até a visita dos trolls. Não documenta seu destino posterior; não se presume sobrevivência após setenta anos. @F',['F'],['Cogu','Rake','Timo'],'baixa')
Q(39,'Furion e documento de continuidade','Furion pertence à continuidade material de Fash e Glim? Se pertence, quando encontrou o grupo, de quem era emissário e qual seu destino?',
  'Furion só foi localizado nesta consulta em Personagens e Heróis, documento marcado revisar_continuidade, como profeta da floresta de traços arbóreos. Não foi equiparado ao ente sem nome do diário. @PH',['PH'],['Furion'],'media','continuidade')
Q(40,'Sobreviventes da Roda de Estopa','Brakka morreu ou desapareceu durante os Doze Dias, e em que circunstâncias? Dornal, Harlom, Rumo e Miri tiveram destinos individuais conhecidos?',
  'O background narra a perda da trupe e conserva o pingente de Brakka, mas recusa descrever a cena final. Não atribui mortes individuais a todos os demais. @B',['B'],['Brakka Pedramansa','Dornal','Harlom Vinte-E-Dois','Rumo','Miri'],'media')
Q(41,'Varo e o assassino de Tom','Qual é o cargo e estado atual de Varo Cinzafrio, e quem era o homem que matou Tom durante o serviço? Há confirmação de ordem de Varo ou apenas vínculo com sua rede?',
  'O background descreve Varo como intermediário e o assassino como homem que acompanha Glim, sem nomeá-lo nessa cena. A morte não foi atribuída nominalmente a Varo. @B',['B'],['Varo','Tom do Cesto','Glim Sombrasselva'],'media')
Q(42,'Família e aldeia de Glim','Quais são os nomes dos pais de Glim, a aldeia e o estado atual da mãe? Nina continua lá e sabe quem a cuida ou o que aconteceu ao pai no cemitério?',
  'No retorno de Glim, Nina relata pai morto nos Doze Dias e mãe viva, incapacitada e cuidada por outros. É a última notícia recuperada, sem data absoluta reconciliada. @B',['B'],['Nina','Glim Sombrasselva','Lugares/Aldeia natal de Glim'],'media')
Q(43,'Vyrix','Vyrix é a grafia correta do dragão de cristal? Que acordo mantém com Folha-Seca e qual seu paradeiro após orientar o grupo?',
  'A síntese do handoff da S17 o identifica como dragão jovem, fornecedor de bestas e dono de covil secreto. A correção do sopro para luz não deve ser revertida por aparência cristalina. @H',['H'],['Vyrix','Folha-Seca'],'media')
Q(44,'Beholder da biblioteca','Qual é a identidade e disposição atual do beholder da biblioteca? O tratado regional ainda o protege e há vínculo pessoal confirmado com o livro do dragão ou Firael?',
  'Fash o observa sem ser visto durante a exploração; a síntese do handoff registra o equilíbrio regional nos mapas atuais. Ele é distinto do beholder de fogo de uma provação. @F @H',['F','H'],['Beholder da biblioteca','Firael'],'media')
Q(45,'Chefe goblin e origem da doença','Quem era o chefe goblin e como adquiriu a condição que invertia acertos e falhas? Há relação demonstrada com a entidade planar ou com as marcas da tenda e da caverna?',
  'A síntese do handoff diferencia o poder observado e as interpretações da fumaça, das idades do corpo e das inscrições; não identifica a causa nem um deus pelo nome. @H',['H'],['Chefe goblin'],'media')
Q(46,'Poderes e identificação divina','A que entidades ou mecanismos correspondem o Fogo Primordial de Okay, as sombras de Glim e a luz de Ryld? O que é confirmação do mestre e o que permanece interpretação de NPCs ou visões?',
  'A caravana manifesta quatro forças; Kord tem relação documentada com Crave, mas Pelor é hipótese para Ryld. A ausência de avatares relatada pelos arquivistas não prova as identidades dos poderes privados. @G @H',['G','H'],['Okay dBoa','Glim Sombrasselva','Ryld','Kord','Pelor'],'alta')
Q(47,'Resposta do duque e prefeito humano','Teodoron Talent soube da morte e do domínio do prefeito de Eral? Qual era o nome do prefeito humano e houve confirmação de ajuda ou de uma pessoa enviada para substituí-lo?',
  'Glim o mata em S12 sem reação defensiva; as cartas explicam o controle. Na volta a Eral, a cidade ainda aguarda ajuda e prefeito, sem comando efetivo. @G @T16 @T18',['G','T16','T18'],['Teodoron Talent','Prefeito humano de Eral'],'media')

N('Fash Paleskin',
  'Gnomo e antigo personagem do jogador, narrador do diário da campanha anterior a Glim. O jogador confirma que pertence à mesma continuidade e fundou o [[Faccoes/Ebano|Ébano]], também chamado Sociedade das Sombras. A referência aproximada de setenta anos é a distância entre a Noite Eterna e Glim; não fixa a idade de Fash. @F @J',
  'Seu diário registra o cativeiro e a revelação de que a experiência de [[Lugares/Lazathar|Lazathar]] era sonho. Após despertar, viaja com [[Personagens/Firael|Firael]] e [[Personagens/Timo|Timo]], ajuda a enfrentar o [[Personagens/Druida Sangrento|Druida Sangrento]], participa da libertação da cidade e administra recursos, pagamentos e passagens. Sua avaliação moral e suas suspeitas são a perspectiva de Fash. @F (25/10, 22/01–29/01).\n\nNo solo dos cerca de 45 dias, ingressa na [[Faccoes/Organizacao do Necromante|organização do Necromante]] após enviar ossos de dragão, recebe pergaminhos e um esqueleto guerreiro e descobre a biblioteca do beholder. Lídia o vigiava antes da iniciação. Não há confirmação de que essa organização tenha virado o Ébano. @F (solo dos 45 dias), @J.\n\nA ruptura com Firael cresce com os jogos do Cérebro, a morte de Rake e as doze derrotas. Fash e Kael entregam Firael vivo ao dragão negro após o duelo dos trolls e fogem separados; Kael é capturado. A entrega e a fundação posterior do Ébano vêm dos esclarecimentos do jogador; a morte de Kael é confirmada pelo mestre na S25. @F (08/02), @J @T25 (01:34:26–01:39:15).\n\nO arquivo de background o chama Tinkar Daergel, filho de Mendrik e Felbira, e narra infiltração na Lâmina da Meia-Noite após a morte dos pais. Essa nota está marcada para revisão de continuidade: Eldrosia, os familiares e o gancho de Jorven não foram promovidos automaticamente a história material confirmada. @FA @J',
  'Fundação do Ébano confirmada; sobrevivência, localização, liderança presente e relação pessoal com a magia de sombras continuam abertas. O jogador acredita que esteja vivo, sem certeza. O antigo diário não cobre toda a continuação conduzida pelo mestre. @J @T25 (01:49:34).',
  ['F','J','T25','FA'],['Faccoes/Ebano','Personagens/Kael','Personagens/Firael','Personagens/Necromante','Eventos/Duelo e entrega de Firael'],[1,2],['Fash'])

N('Glim Sombrasselva',
  'Gnomo, artista e conjurador de sombras, personagem do jogador na campanha atual. Usa títulos como O Magnífico e Grande Mago das Sombras; são autodescrições e persona de palco, não medidas objetivas de poder. O jogador aprovou seu background como cânone observado o ponto de vista de Glim. @B @J',
  'Na infância, encontra o [[Itens/Grimorio de Glim|grimório]] na floresta com o irmão Lilo e Piche. A tentativa de um efeito maior rompe algo semelhante a um selo e libera a sombra que mata ambos. Rejeitado ao voltar sozinho, foge levando o livro e o corpo de Piche. A culpa de Glim é documentada; a vontade da sombra e a origem do livro não estão explicadas. @B (ato 1).\n\nBrakka o acolhe na [[Faccoes/Roda de Estopa|Roda de Estopa]], onde aprende a usar o espetáculo como trabalho e abrigo. Os Doze Dias Rubros desagregam a trupe e ele perde Brakka. Depois trabalha como distração para Varo, evita reconhecer plenamente a violência dos serviços e rompe essa conveniência após presenciar a morte de Tom. Investiga o Ébano e percebe afinidade entre suas sombras e o livro; isso é interpretação sua. @B (atos 2–6).\n\nRetorna à aldeia, recebe de Nina a notícia do pai morto e da mãe incapacitada, e guarda memoriais deles, de Tom, Brakka e Piche. Busca trabalho em Carruan e segue para Eral, onde conhece Okay, Crave e Ryld e contrata serviços com Arkhavel em troca de recursos e biblioteca. O nome Lazathar para a capital no diário atual é erro corrigido pelo jogador. @B (ato 6), @G (S1), @J.\n\nParticipa da queda dos esquemas de Eral, da busca fracassada dos rangers e do retorno à cidade atacada. As atrocidades nas cavernas também o implicam: a recapitulação do mestre registra a ordem de bloquear a saída, o recuo dos goblins e quinze reféns mortos nos setores que não conseguiu isolar. Sua narrativa heroica não elimina esses fatos. @G @T18 @T23 (00:07:25–00:08:51).\n\nNa S24 sacrifica a magia Caltrops durante a provação associada ao Fogo Primordial. Crave perde sua sombra para que uma forma de Lilo saia do grimório como familiar. O primeiro fato é resumido no handoff; o segundo foi conferido diretamente na transcrição, que não confirma a alma original do irmão. @H (Magia, objetos e cosmologia), @T24 (03:03:17–03:05:26).',
  'Até S26, chama a torre de casa, estuda suas portas e defesas com os companheiros e enfrenta Vesperal. O encerramento confirma a ida ao Etéreo. Permanecem abertas a natureza do livro e das visões, a identidade espiritual do familiar e a notícia da morte da taverneira que pode ainda não conhecer. @T26 @H',
  ['B','J','G','T18','T23','H','T24','T26'],['Personagens/Lilo Sombrasselva','Personagens/Piche','Personagens/Varo','Personagens/Crave','Personagens/Okay dBoa','Itens/Grimorio de Glim','Lugares/Torre de Arkhavel'],[9,10,11,24,42,46],['Glim','O Magnífico','Grande Mago das Sombras'],['glim'])

N('Okay dBoa',
  'Arquivista que estuda magia divina, cura e invoca, companheiro de Glim e reencarnação confirmada de [[Personagens/Kael|Kael]]. Glim o descreve como elfo cinza na caravana; o dossiê diz meio-elfo de ascendência humana e elfa cinzenta. A ascendência fica explicitamente divergente. @G (S1), @OK (Quem é Okay), @J',
  'Trabalha com Arkhavel e os Magníficos nos casos de Eral. Sua experiência no amuleto é tratada, na síntese do handoff, como percurso por lugares planares corroborado por conhecimentos novos e consultas posteriores, preservando visões e interpretações específicas. Rudiger e Kord entram nesse percurso; não se presume que tudo visto seja avatar material. @G (S17), @H (Experiência de Okay no amuleto).\n\nO Fogo Primordial já estava nele antes do despertar da S24, segundo a síntese do handoff; a analogia com poderes de outro plano não identifica uma divindade patrona. Glim cede Caltrops durante a provação. O dossiê acrescenta uma história familiar e uma leitura de sua postura perante os deuses; essa camada exige revisão e não substitui a cronologia confirmada da reencarnação. @H (Forças dos Magníficos e divindades), @OK.\n\nNa S25, mapas e pergaminhos restauram a vida anterior como Kael: recorda fuga e morte pelo dragão e reconhece a letra de Firael. O mestre limita a recuperação àquela vida, excluindo lembranças de vidas ainda anteriores que Kael havia recuperado. Também lembra a mulher capaz de devolver memórias. Decide guardar de Glim a identidade de Timo como planta/cajado. @T25 (01:34:26–01:39:15; 01:51:24–01:51:56).\n\nTahen estudou com ele e traz notícias de expedições desaparecidas, inclusive do antigo professor de Okay. A organização élfica atual e os Zodíacos não foram demonstrados como a mesma entidade. @T24 (01:57:35; 02:09:57; 02:20:24), @H (Arquivistas, Lua Sangrenta e Zodíacos).',
  'Ao fim de S26 está vivo e participa dos estudos e preparativos da torre após enfrentar Vesperal. A reencarnação não torna automaticamente públicas todas as suas lembranças nem transmite a Glim os segredos que escolheu reter. Seus destinos propostos — região antiga, arquivistas e mulher das memórias — permanecem planos até execução documentada. @T25 @T26',
  ['G','OK','J','H','T24','T25','T26'],['Personagens/Kael','Personagens/Tahen','Personagens/Elrohir','Personagens/Mulher das memorias','Itens/Fogo Primordial','Faccoes/Arquivistas'],[3,4,7,10,31,46],['Okay',"Okay d'Boa",'Okay d’Boa'])

N('Kael',
  'Mago humano da campanha antiga, chamado Kael no diário e também transcrito Cael. Sua reencarnação como Okay é confirmação direta do jogador; as duas vidas são ligadas sem apagar a separação biográfica. @F (20/8/530), @J',
  'Chega com um grupo misto para verificar a situação local, permanece por saber drow e auxilia a leitura do diário do Druida Sangrento. Desfere o golpe fatal no drow; Firael o decapita. Após a transferência da autoridade das coleiras, liberta os anões e ajuda a negociar a proteção dos reassentados. @F (20/8/530, 22/01 e 25/01).\n\nAuxilia a explorar portais, interpreta o desgaste das runas da prisão e participa do plano de perguntas ao Cérebro. Com Fash, entrega Firael vivo ao dragão após o duelo dos trolls. Os dois fogem separados; o mestre confirma que o dragão captura, tortura, mata e come Kael. Firael ter consumido seu cérebro é hipótese explicitamente negada na S25. @F (18/01–08/02), @J @T25 (01:34:26–01:39:15).',
  'Morto na vida antiga; continuidade atual em Okay, que recupera essa vida na S25. Memórias mais remotas que Kael havia acessado não foram recuperadas nesse ato. @J @T25 (01:37:50–01:38:10).',
  ['F','J','T25'],['Personagens/Okay dBoa','Personagens/Fash Paleskin','Eventos/Morte de Kael'],[4,36],['Cael'])

N('Crave',
  'Humano combatente que usa correntes e porta o [[Itens/Amuleto de Kord|amuleto de Kord]]. A força invisível que se manifesta na caravana é experimentada pelos quatro companheiros; a identificação e os ensinamentos religiosos se desenvolvem depois. @G (S1 e S17).',
  'Foi treinado por Rudiger Quebra-Ferro, mentor mercenário que lhe deu o amuleto. Tólomon propõe que Rudiger pudesse ser Kord ou uma forma dele, sem prova definitiva. Crave trabalha com Glim, Okay e Ryld nos serviços de Arkhavel e nas crises de Eral. @G (S17), @H.\n\nMata indefesos nas cavernas, inclusive após ficar na saída por ordem de Glim. O mestre recapitula que o bloqueio leva goblins a retornar e quinze reféns humanos morrem nos setores não salvos. Tariun o confronta com a covardia de matar fracos por medo de seu futuro e oferece caminho de redenção; Crave recusa o recrutamento de Hextor. @T23 (00:07:25–00:16:58; 00:26:47), @H (Igreja de Kord e forças rivais).\n\nNa montanha escolhe o rito do cinto enquanto os companheiros tentam salvar fugitivos. A figura de seu prelúdio recolhe o sacerdote vivo e manifesta decepção. A síntese do handoff registra retorno do torneio exausto, com três pontos cumulativos de Força e sem o cinto. Esse objeto é distinto do amuleto. @T23 (03:46:30–03:47:26), @H (S24).\n\nNa provação das sombras, perde progressivamente sua sombra até permitir a manifestação do familiar de Glim com forma de Lilo. A perda inteira é confirmada em cena. Tariun depois o adverte sobre possível conflito entre Glim e Okay; Crave rejeita escolher e conta o aviso a Glim, segundo a síntese do handoff. @T24 (03:03:17–03:05:26), @H (S25).',
  'Vivo ao fim de S26, participa do combate a Vesperal, que deseja seu amuleto e drena vitalidade. A destruição do corpo do inimigo não resolve a ameaça do possessor. A ausência de sombra está documentada; seu alcance espiritual e o estado final da redenção continuam abertos. @T24 @T26',
  ['G','H','T23','T24','T26'],['Personagens/Rudiger','Personagens/Tariun','Personagens/Kord','Personagens/Hextor','Personagens/Lilo Sombrasselva','Eventos/Crise dos refens'],[12,13,30,46],['Kraven','Krave'],['glim'])

N('Ryld',
  'Drow arqueiro, companheiro dos Magníficos e contratado de Arkhavel. Na caravana manifesta luz que reage ao fogo de Okay. A hipótese de ligação com Pelor é de Tólomon, não identidade divina confirmada. @G (S1 e S17).',
  'A síntese do handoff registra infiltração no submundo, captura e resgate por Arkhavel. Trabalha também em contratos planares: na S20 diz que resolveu os demais serviços e faltam os escaravelhos; sua ausência em outras expedições não o torna desaparecido. @H (Pessoas e seres), @T20 (00:08:33–00:15:41).\n\nSua luz se distingue das sombras de Glim, do fogo de Okay e da pressão de Crave. O documento Personagens e Heróis traz uma família de Ryldan Velkyn, mas está marcado para revisão; essa biografia não foi integrada a Ryld por semelhança do nome. @G (S1), @PH',
  'Na síntese do handoff, fica encarregado de inspecionar o posto dos Mind Shredders; não há resultado confirmado nesta consulta nem localização final assegurada. Não confundir esses seres com os devoradores de mente de Firael. @H (Mind Shredders).',
  ['G','H','T20','PH'],['Personagens/Pelor','Personagens/Arkhavel','Faccoes/Magnificos'],[14,46],[],['glim'])

N('Arkhavel',
  'Artificer que se apresenta como Arcanista dos Véus Interplanares; possui torre em Eral, biblioteca, laboratório e rede de portas. Corrige o grupo quando o chama de mago. Cobra informação e trabalho, frequentemente por pagamentos concretos. @G (S1–S2).',
  'Contrata o grupo para capturar um elemental da tempestade, empregado numa invenção de limpeza. Oferece acesso à biblioteca por parceria de trabalho. Sua mesa de análise revela que Tauro é um golem feito com restos de 32 ajudantes e um item que lhe confere forma e consciência; o surgimento da mulher a partir do braço o surpreende. @G (S1–S2).\n\nTeletransporta o grupo à casa do prefeito e depois enfrenta o Aboleth e toma seu tesouro. O dossiê de Okay relata exame e interrogatório do Kuat como criação do artificer; essa informação derivada é preservada com pendência sobre a identidade precisa do filho citado nas cartas. @G (S12), @OK (7.10).\n\nT16 relata sua saída para procurar filhos e distingue Donovan do filho ligado ao prefeito. As cartas julgam que Arkhavel despreza os filhos e que os Magníficos seriam seus experimentos; são avaliações interessadas, não prova da origem do grupo. A existência de clones é registrada na síntese do handoff, sem autorização para identificar todo encontro como um clone. @T16 (00:34:00; 01:17:32–01:27:54), @H (Arkhavel e suas relações).',
  'Ausente da torre, sem retorno datado nesta documentação. Os companheiros estudam sua rede e as defesas até S26. Os problemas derivados de suas criações e as relações familiares não estão resolvidos. @T16 @T26',
  ['G','OK','T16','H','T26'],['Lugares/Torre de Arkhavel','Itens/Mesa de analise','Personagens/Tauro','Personagens/Donovan','Personagens/Filho de Arkhavel ligado ao prefeito'],[15,16,17,18,19])

N('Timo',
  'Druida da campanha antiga, ligado à floresta e aos companheiros Cogu e Rake. Teemo aparece como variante de transcrição. O jogador confirma que é o antigo personagem que morreu, virou planta e cuja planta se tornou o cajado de girassol. @F @J @T25',
  'Participa do sonho e da fuga da cabana, combate a corrupção das bruxas e o Druida Sangrento, molda rochas para passagens e para vedar temporariamente o Cérebro. Cogu fica com a matilha; Rake torna-se sua montaria e companheiro. Após a morte de Rake, reaparece com asas e traços ferais, retornando gradualmente à aparência usual naquela cena. @F (31/10, 18/01, 25/01 e 29/01).\n\nCriaturas da floresta o homenageiam como escolhido de Silvanus e pedem ajuda com zumbis e animais em transe. Fash registra a escolha, mas admite desconhecer seu significado completo. Uma posterior armadura animada busca Cogu; Kael e Timo o protegem. @F (08/02 e Dia 45).\n\nA ausência de Timo na fuga de Fash e Kael tem motivação apenas lembrada como possibilidade pelo jogador. Sua morte não tem causa recuperada. S25 identifica a planta que virou artefato maior da dríade como o antigo companheiro; não identifica a portadora como reencarnação dele. @J @T25 (01:51:24–01:51:56).\n\nO Resumo detalhado se refere a Timo Pé-de-Musgo e Fesh e usa datas conflitantes. É uma síntese derivada a revisar: não transfere automaticamente sobrenome, cronologia ou atos divergentes ao diário de Fash. @TIM @F',
  'Morto como pessoa da campanha antiga, com continuidade confirmada em planta/cajado de girassol portado por dríade. Consciência, vontade, mecanismo da transformação e condição presente não foram esclarecidos. Okay lembra dessa identidade e decide guardá-la de Glim. @J @T25',
  ['F','J','T25','TIM'],['Personagens/Cogu','Personagens/Rake','Personagens/Silvanus','Personagens/Driade do cajado de girassol','Itens/Cajado de girassol'],[5,6,38],['Teemo'])

N('Firael',
  'Antigo companheiro da campanha de Fash, descrito como paladino e mais tarde com escamas e traços dracônicos. Está vivo e comanda a [[Faccoes/Organizacao de Firael|organização dos devoradores de mente]], tendo o Cérebro como chefe superior: isso é confirmação explícita do mestre em off. @F @T25 (01:35:35).',
  'Aproxima-se do Cérebro e aceita seus jogos, contrariando acordos do grupo. Enquanto está na sala fechada com ele, Timo encontra o Druida Sangrento e Rake morre. Após a vitória sobre o drow, Firael o decapita; o golpe fatal fora de Kael. Fash narra doze derrotas nos jogos quando se haviam combinado quatro tentativas. Controle mental é suspeita dos companheiros, não diagnóstico demonstrado. @F (18/01, 22/01, 29/01 e 08/02).\n\nFica gravemente ferido pelo troll e é entregue vivo por Fash e Kael ao dragão negro. Tenta roubar o livro do dragão e sobrevive por acordo, porque o dragão teme o Cérebro. A entrega vem dos esclarecimentos; o acordo e a tentativa de roubo são também confirmados pelo mestre na S25. @J @T25 (01:35:35; 02:19:10–02:19:42).\n\nNa campanha atual, mapas e pergaminhos têm sua letra, reconhecida por Okay ao recuperar a vida de Kael. O mestre explica que informações particulares, como um nodo, vieram do Cérebro. Sua organização recolhe corpos para consumir conhecimentos dos cérebros. A hipótese de ele ter comido o cérebro de Kael é negada: Kael foi comido pelo dragão. @T25 (01:35:18–01:39:15; 01:43:25).',
  'Vivo e dirigente atual confirmado, subordinado ao Cérebro. Não há encontro presencial atual documentado nesta consulta. Se reconhece Okay como Kael e por que mobiliza os Magníficos contra interesses de seu aliado Mercado Negro são dúvidas explícitas. Tyrael/Tyrell não foram adotados como nomes canônicos. @T25 (01:36:35; 01:49:34–01:55:22).',
  ['F','J','T25'],['Personagens/Cerebro Anciao','Personagens/Dragao negro','Personagens/Okay dBoa','Faccoes/Organizacao de Firael','Itens/Mapas e pergaminhos de Firael'],[7,8,36])

N('Rake','Dinossauro companheiro e montaria de Timo, apresentado após Cogu ficar com a matilha. Fash e o grupo encomendam armadura para ele. @F (31/10 e 24/11).',
  'Participa dos combates com o Druida Sangrento e chega a ser dominado por sua magia. Morre quando Timo corre para auxiliar Firael, que está trancado com o Cérebro. Fash encontra o corpo na sala antimagia, com garras e veneno como sinais do drow. @F (15/12 e 18/01).',
  'Morte confirmada no diário. A perda fratura as relações do grupo e precede a homenagem a Timo como escolhido de Silvanus; não demonstra sozinha o mecanismo da transformação do druida. @F (18/01 e 08/02).',['F'],['Personagens/Timo','Personagens/Druida Sangrento','Personagens/Firael'],[38])

N('Elena','Elena Tanziam se apresenta como pessoa de outro continente, morta havia mais de um século e escravizada numa esfera capaz de criar mundos de sonho. O livro das bruxas usa Serethyn e contesta ou amplia essa biografia. Natureza divina ou cósmica é hipótese, não identificação confirmada. @F (25/10 e 07/11).',
  'Aparece no trecho onírico e revela que o grupo nunca saíra do cativeiro. Ao despertar, a esfera amarelada permanece associada a ela. Pede sua destruição para interromper a escravidão. Explica nodos e teoriza que uma bruxa teria sacrificado outra para o ritual do ente corrompido; ambas são falas atribuídas, não verdade onisciente. @F (25/10, 31/10, 07/11 e 02/12 solo).',
  'A destruição do artefato produz um pilar de luz e fenômenos posteriores; o destino pessoal de Elena não está inequivocamente documentado. Serethyn é mantido como nome relacionado da fonte, sem escolher uma das biografias como verdade final. @F (01/12), @H (Destruição do artefato).',['F','H'],['Personagens/Grixxian','Personagens/Morvessh','Itens/Esfera de Elena'],[32,33],['Elena Tanziam','Serethyn'])

N('Morvessh','Bruxa da Lua, uma das três do Círculo Vetrilus com Selara e Lyvessa. O livro das bruxas liga o círculo à descoberta de um nodo e à fabricação do artefato de Elena. É informação extraída desse livro. @F (07/11).',
  'O diário a coloca entre as perseguidoras do grupo após a fuga. O livro e os relatos de Elena descrevem sequestros, demônio e vassalos. A hipótese de uma irmã sacrificada para alimentar um ritual é de Elena; não constitui morte confirmada de Morvessh, Selara ou Lyvessa. @F (31/10, 07/11, 28/11).',
  'O jogador atribui a Noite Eterna à bruxa e à continuação da campanha, mas não individualiza aqui a autora nem confirma quais irmãs sobreviveram. O estado atual de Morvessh permanece aberto. @J',['F','J'],['Faccoes/Circulo Vetrilus','Personagens/Selara','Personagens/Lyvessa','Personagens/Elena','Eventos/Noite Eterna'],[32])
N('Selara','Bruxa do Mar, integrante do Círculo Vetrilus junto de Morvessh e Lyvessa segundo o livro das bruxas. @F (07/11).',
  'É relacionada à origem e às práticas do círculo pelo livro encontrado pelo grupo. Elena interpreta o ritual do ente corrompido como possível sacrifício de uma bruxa pela outra, mas a leitura não fixa qual irmã nem comprova o sacrifício. @F (31/10 e 07/11).',
  'Sobrevivência, atividade e participação individual na Noite Eterna não confirmadas. Não se preenche essa lacuna atribuindo a Selara todos os atos do círculo. @F @J',['F','J'],['Faccoes/Circulo Vetrilus','Personagens/Morvessh','Personagens/Lyvessa'],[32])
N('Lyvessa','Bruxa da Grama, integrante do Círculo Vetrilus junto de Morvessh e Selara segundo o livro das bruxas. @F (07/11).',
  'O registro a vincula ao círculo, ao nodo e à história do artefato; não oferece uma biografia individual equivalente à de Elena. A possível morte de uma irmã num ritual continua teoria de Elena sem identificação conclusiva. @F (31/10 e 07/11).',
  'Destino e atividade atuais não confirmados; não há base para declarar sua morte ou identificá-la como causadora individual da Noite Eterna. @F @J',['F','J'],['Faccoes/Circulo Vetrilus','Personagens/Morvessh','Personagens/Selara'],[32])
N('Grixxian','Nome do demônio de cinzas que aprisiona Elena no trecho onírico, segundo a síntese do handoff. Relatos posteriores o relacionam à bruxa; isso não valida a hierarquia aparente dentro do sonho. @H (Antagonistas e contatos históricos).',
  'O diário descreve as camadas de cativeiro, o demônio e a revelação de Elena de que os personagens não haviam escapado. Combates vividos nesse contexto são experiências dos personagens, sem confirmação de morte material do ser. @F (25/10), @J',
  'Existência, papel e destino fora do sonho não resolvidos. O nome é mantido como referência histórica da síntese, sem transformá-lo em comandante material demonstrado das bruxas. @H',['H','F','J'],['Personagens/Elena','Personagens/Morvessh','Lugares/Plano dos sonhos'],[33])
N('Lidia','Fantasma ligado ao Necromante e encarregado de vigiar Fash desde seu primeiro encontro com ele. A vigilância é revelada pelo próprio Necromante. @F (08/02 e solo dos 45 dias).',
  'Ajuda a identificar ossos de dragão para a tarefa de ingresso de Fash. Informa sobre a passagem subterrânea sob o fosso; o Necromante diz ter perdido seu vínculo com ela ao se aproximar dessa passagem. Após a iniciação de Fash, a vigilância deveria cessar. @F (solo dos 45 dias).',
  'A última situação recuperada é a atuação no período de iniciação e a notícia da perda de vínculo junto da passagem. Não há destino atual confirmado nem prova de destruição do fantasma. @F',['F'],['Personagens/Necromante','Personagens/Fash Paleskin','Lugares/Fosso de ossos e nodo'],[34],['Lídia'])
N('Necromante','Contato dissidente do sistema de vassalos das bruxas, chamado apenas O Necromante; nome próprio não recuperado. Propõe proteção regional e aliança contra as bruxas. @H (Bruxas, nodo e Elena), @F (28/11 e solo dos 45 dias).',
  'Mantém Lídia vigiando Fash, oferece meios de garantir uma morte e depois o inicia em sua organização em troca de ossos de dragão. Explica regras de contribuição e preservação do grupo, entrega pergaminhos e um esqueleto e pede investigação da passagem onde perdeu o vínculo com Lídia. Considera Firael um risco, sem ordenar eliminação direta. @F (08/02 e solo dos 45 dias).\n\nDescreve o Cavaleiro da Morte adormecido como ameaça que mobilizaria mortos-vivos numa guerra caótica, e informa uma necrópole junto ao rio, abaixo dos Equiceps. Isso é informação do NPC, não prova de que a ameaça se concretizou. @F (solo dos 45 dias).',
  'Destino pessoal e estado da necrópole abertos. A hipótese de o Cavaleiro ter despertado e tomado o lugar é condicional na memória do jogador. Sua organização não foi demonstrada como o próprio Ébano. @J',['H','F','J'],['Personagens/Lidia','Personagens/Cavaleiro da Morte','Faccoes/Organizacao do Necromante','Lugares/Necropole'],[34],['O Necromante'])
N('Druida Sangrento','Drow guardião do Cérebro, escravizador dos anões e sobrevivente de uma guerra antiga. O diário dele, lido pelo grupo, conta o aprisionamento do Cérebro por quatro povos, a guerra e o pacto com Lolth que destruiu as civilizações anã e drow. Essa história é relato documental interno. @F (15/01).',
  'Usa zumbis, venenos, aranhas e golems, foge de confrontos e se disfarça para dividir os adversários. Substitui o anão guardião, descobre Firael sozinho e corre para atacá-lo; Rake morre na sequência. A família do anão era mantida escravizada como coação. @F (15/01 e 18/01).\n\nFash supõe que Lolth o puniria com transformação em drider; essa expectativa não é confirmação de que ocorreu. Na batalha final Kael o mata e Firael o decapita. As coleiras passam a Kael após 24 horas, permitindo a libertação dos anões. @F (15/01, 22/01 e 25/01).',
  'Morto na campanha antiga, com autoria do golpe fatal registrada. Nome pessoal não recuperado; não confundir sua escravização dos anões com adesão voluntária do guardião coagido. @F',['F'],['Personagens/Kael','Personagens/Anao guardiao','Personagens/Lolth','Personagens/Cerebro Anciao','Personagens/Rake'],[35])
N('Cogu','Companheiro de Timo associado a uma matilha; a fonte Personagens e Heróis o chama lobo, mas é documento em revisão. O diário de Fash confirma Cogu e sua relação com a matilha sem depender de uma genealogia inventada. @F (31/10), @PH',
  'Permanece na floresta quando uma criatura alada ameaça o território, enquanto Timo passa a montar Rake. Pelos de Cogu e runas são associados ao rastreamento das bruxas; no Dia 45 uma armadura animada segue até ele e é combatida por Kael e Timo. A origem do rastreamento é interpretação do grupo. @F (31/10 e Dia 45), @H (Bruxas, nodo e Elena).',
  'Protegido na floresta no último episódio recuperado do diário antigo. Não há sobrevivência ou destino atual confirmado após o intervalo histórico. @F',['F','PH','H'],['Personagens/Timo','Personagens/Rake','Lugares/Floresta de Timo'],[38])
N('Anao guardiao','Anão guardião ou ferreiro da fase material da campanha antiga, sem nome pessoal recuperado. O relato transmitido pelo Cérebro e por Firael diz que sua família escravizada era usada pelo drow para coagi-lo; não era um guardião livre em igualdade com ele. @F (18/01).',
  'O Druida Sangrento também usa sua aparência como disfarce: o interlocutor que descobre Firael sozinho e corre para atacá-lo é o drow, não prova de traição do anão real. O relato da amante integra a manipulação. O anão das sete portas pertence ao sonho e não foi identificado como esta pessoa. @F (15/01, 18/01 e 16/08), @J',
  'Destino individual e o de sua família após a libertação dos anões não recuperados. A libertação geral por Kael não basta para inventar seu cargo posterior ou equiparar todos os ferreiros anões citados. @F (25/01).',['F','J'],['Personagens/Druida Sangrento','Personagens/Cerebro Anciao','Personagens/Kael'],[35],['Anão guardião'])
N('Dragao negro','Dragão negro sem nome recuperado, poder regional ligado aos trolls, tributos e ao livro que Firael tentou roubar. Sua posição regional é resumida no handoff; não se acrescenta lore externo à espécie. @H',
  'Recebe Firael vivo de Fash e Kael após o duelo. O dragão aguarda que ele acorde e negocia ao temer o Cérebro. Persegue os fugitivos separados, captura Kael, tortura-o e o come. A entrega é memória confirmada do jogador; o acordo e a morte de Kael são confirmados pelo mestre na S25. @J @T25 (01:34:26–01:39:15).',
  'Atuação antiga confirmada; localização, nome e condições atuais pedem confirmação. Não confundir seu território com o covil marítimo das expedições de arquivistas desaparecidos, que é outro destino descrito no handoff. @H',['H','J','T25'],['Personagens/Firael','Personagens/Kael','Lugares/Cidade ana dos trolls','Itens/Livro do dragao negro'],[36],['Dragão negro'])
N('Hourian Haurim','Hourian é o nome de um dragão vermelho no relato de Firael, apresentado como benéfico ao progresso das outras raças e adversário de dragões malignos. É tradição relatada pelo NPC. A relação com a grafia Haurim dos covis é plausível, mas não confirmada nesta consolidação. @F (01/12 e 08/02).',
  'Elena reconhece uma estatueta como sendo de Hourian; Fash oculta dela a origem da informação ao conversar com Firael. Firael afirma que Hourian combateu e eliminou dragões malignos, influenciou o início dos cultos dracônicos e morreu contra uma grande revoada. @F (01/12 e 02/12 solo).',
  'Morto segundo o relato histórico de Firael; a revoada não foi identificada como Revoada Branca. O nome muito expandido presente em Personagens e Heróis está em fonte de continuidade a revisar e não foi adotado como alias confirmado. @F @PH',['F','PH'],['Lugares/Covis de Hourian Haurim','Eventos/Revoada Branca','Personagens/Firael'],[37])

N('Tork','Guarda de Eral que resiste à corrupção. O mestre explica que sua capacidade de investigar era contida por represálias contra mulheres, crianças e idosos; não é demonstrado como cúmplice apenas por conhecer o problema. @T13 (00:16:28; 01:17:19).',
  'Ajuda na investigação dos gnolls e exige prova. Planeja e executa a purga de guardas por emboscadas individuais, usando sua autoridade para convocá-los; não vence todos de frente. A síntese do handoff registra sua nomeação como Primeiro Magnífico Honorário e o acordo relutante com Folha-Seca para apagar seis nomes em troca de ajuda contra guardas viajantes. @G (S2), @T13 (01:13:41), @H (Conclave e comunidade da floresta).',
  'Morto no ataque a Eral. O grupo encontra seu corpo, reconhece-o e vê as costas esfaqueadas; o mestre vincula a morte aos Kenku. Não há ambiguidade de sobrevivência a preencher. @T18 (01:11:11–01:14:24).',['T13','G','H','T18'],['Personagens/Folha-Seca','Personagens/Kenku caolho','Eventos/Ataque a Eral'],[29],[],['glim'])
N('Folha-Seca','Darian Folha-Seca Valek, ranger ligado à comunidade da floresta e informante sobre problemas de Eral, água e desaparecimentos. Nome completo e primeiros contatos constam da síntese do handoff. @H (Eral, floresta e contatos atuais).',
  'Corrige a versão de que os rangers teriam entrado no negócio da arena para salvar animais: essa proibição veio depois como exigência da comunidade. Negocia eliminar guardas fora da cidade em troca de apagar seis nomes e negar o vínculo criminal; Tork aceita relutantemente. São atos políticos específicos, não prova de inocência coletiva. @H (Conclave e comunidade da floresta; síntese de S14–S16).\n\nUma amiga já havia desaparecido antes da missão contra os guardas. Esse sumiço é anterior e não deve ser reescrito como parte da expedição subsequente. @H',
  'Desaparecido com a expedição na última notícia recuperada. Na volta a Eral ninguém viu rangers ou druidas; Glim teme que estejam mortos, mas isso é temor de personagem. @T18 (01:11:11; 01:15:18).',['H','T18'],['Personagens/Hanta','Personagens/Tork','Lugares/Comunidade da floresta','Eventos/Busca dos rangers'],[26,27],['Darian Folha-Seca Valek','Folha-Seca'],['glim'])
N('Hanta','Jovem ranger que guia a caça ao Vasuthant. A síntese do handoff registra que recusa pagamento e recebe bolos do grupo. @H (Eral, floresta e contatos atuais; S7–S8).',
  'É associado às buscas e ao grupo de rangers desaparecido. Sua relação com Folha-Seca e a missão deve ser conservada sem lhe atribuir automaticamente cada ato dos rangers envolvidos com a arena. @H',
  'Sem destino confirmado após a busca fracassada e o ataque a Eral. A fala de Glim de que Hanta e Folha-Seca devem estar mortos não é confirmação do mestre. @T18 (01:15:18).',['H','T18'],['Personagens/Folha-Seca','Eventos/Caca ao Vasuthant','Eventos/Busca dos rangers'],[26],[],['glim'])
N('Tolomon','Responsável religioso da igreja de Kord em Eral, tratado como interlocutor principal nas negociações do grupo. Recebe a notícia do perigo de Ryld e resiste a libertar um criminoso que matou um membro da igreja. @G (S11).',
  'Negocia apoio contra o prefeito e a arena. Explica que o amuleto de Crave era tradicionalmente usado por Kord e talvez estivesse adormecido. Ao ouvir Rudiger Quebra-Ferro, sugere ligação com o deus e faz reverência; a identificação do mentor como Kord continua hipótese dele. Também conjectura Pelor para Ryld e divindade do fogo para Okay. @G (S14 e S17).',
  'Destino individual no ataque a Eral não estabelecido com segurança. A morte dos clérigos combatentes é confirmada, mas a transcrição não o identifica inequivocamente entre eles. @T18 (01:14:24), @H',['G','T18','H'],['Personagens/Kord','Personagens/Crave','Personagens/Rudiger','Lugares/Igreja de Kord em Eral'],[13,25],['Tólomon'],['glim'])
N('Tariun','Sacerdote troglodita de Kord em Mercadia; diz que Tariun é como os humanos o chamam. Recebe Crave e discute força, responsabilidade e redenção. @T23 (00:07:25–00:16:58).',
  'Condena matar indefesos por medo de seu poder futuro e lembra as consequências para os reféns. Ensina proteção, desafio e competição como uso da força e propõe prisão e justiça como alternativas. A síntese do handoff registra a devolução do colar e sua advertência de que Glim e Okay podem destruir um ao outro, colocando Crave diante de uma escolha. @T23 @H (Igreja de Kord; consequências).',
  'Parte para concluir a tarefa da montanha, sem resultado registrado até S26 na síntese consultada. Seu aviso é advertência ou profecia, não futuro consumado. @H (S25).',['T23','H'],['Personagens/Kord','Personagens/Crave','Lugares/Mercadia','Eventos/Provacoes de Kord'],[30],[],['glim'])
N('Rudiger','Rudiger Quebra-Ferro, mentor mercenário de Crave, de cabelos brancos, comportamento calmo e usuário de correntes. Deu-lhe o amuleto associado a Kord e depois desapareceu de sua vida. @G (S17), @H (Contatos religiosos e planares).',
  'Tólomon associa seu nome e o presente a Kord e sugere que fosse o deus ou uma forma dele. Na prova da neve aparece a figura do prelúdio de Crave, que recolhe vivo o sacerdote abandonado e demonstra decepção. A conexão de identidade entre essas aparições ainda não é demonstração conclusiva de avatar. @G (S17), @T23 (03:46:30–03:47:26).',
  'Paradeiro e natureza atuais desconhecidos. A crença de Crave no mestre não foi promovida a confirmação onisciente de que toda aparição era Kord. @H @T23',['G','H','T23'],['Personagens/Crave','Personagens/Kord','Itens/Amuleto de Kord'],[13],['Rudiger Quebra-Ferro'],['glim'])

N('Lilo Sombrasselva','Irmão gnomo de Glim, companheiro de sua exploração da floresta e associado ao corvo Piche. É dele a frase “Se você acredita, é real”, usada para encorajar o irmão. @B (ato 1).',
  'Acompanha Glim quando este tenta uma página nova do grimório. O selo aparente se rompe, uma sombra se ergue e mata Lilo e Piche; o background contém também a perspectiva de Lilo sobre os últimos instantes. O jogador aprovou o background observado esse regime de perspectiva. @B @J\n\nNa S24, após Crave perder sua sombra inteira, uma sombra com a forma do irmão sai do grimório. O mestre a define como familiar de Glim com capacidades derivadas dele e características de sombra. Isso estabelece a manifestação e a relação funcional, sem confirmar que a alma original retornou. Visões anteriores de Lilo são experiências sujeitas a manipulação segundo a síntese do handoff. @T24 (03:03:17–03:05:26), @H (Grimório e sombra de Lilo).',
  'Lilo original morreu na infância de Glim; uma forma de Lilo atua atualmente como familiar. Na S25, o jogador atualiza a ficha com Toque Fantasma para que ele possa pegar objetos e cogita levá-lo em viagem; isso não confirma a identidade da alma. Não se descreve ressurreição completa nem se toma uma fala de visão como confissão histórica dele. @B @T24 @T25 (02:19:57–02:20:38), @H',['B','J','T24','T25','H'],['Personagens/Glim Sombrasselva','Personagens/Piche','Personagens/Crave','Itens/Grimorio de Glim'],[9,10,11],['Lilo'],['glim'])
N('Piche','Corvo de Lilo e, afetivamente, também de Glim; acompanha os irmãos à floresta e frequentemente pousa no ombro de Glim. @B (ato 1).',
  'É morto pela sombra libertada durante a tentativa de Glim com o grimório. Glim volta à clareira, envolve o corpo e o leva consigo ao fugir. Ao longo das perdas da trupe e de outros vínculos, conserva Piche junto ao peito. Isso é um vínculo afetivo documentado, sem poder mágico específico estabelecido. @B (atos 1–3 e 6).',
  'Morto; corpo carregado por Glim. Não há ressurreição confirmada ou base para equipará-lo à sombra familiar de Lilo. Condição sobrenatural do corpo permanece aberta. @B',['B'],['Personagens/Lilo Sombrasselva','Personagens/Glim Sombrasselva','Itens/Memorias materiais de Glim'],[11],[],['glim'])
N('Brakka Pedramansa','Anã da Roda de Estopa que acolhe Glim e assume responsabilidade por ele diante de Dornal. Sua perspectiva descreve o acolhimento e a persona O Magnífico como proteção do menino. @B (ato 2).',
  'Protege e alimenta Glim, acompanha seus truques e reconhece seus limites sem forçar a confissão do passado. Durante os Doze Dias Rubros salva uma criança sob uma roda e é ferida no braço. No sétimo dia diz a Glim que procure alguém para quem voltar. @B (atos 2–3).',
  'Glim a perde durante a crise, guarda seu pingente e não narra as circunstâncias finais. A perda é clara, mas a nota não inventa modo de morte nem cena omitida. @B (ato 3).',['B'],['Faccoes/Roda de Estopa','Personagens/Glim Sombrasselva','Itens/Memorias materiais de Glim','Eventos/Queda da Roda de Estopa'],[40],['Brakka'],['glim'])
N('Dornal','Dornal Três Dedos, mestre de pista da Roda de Estopa. Inicialmente prefere dispensar Glim para evitar problemas, mas aceita a decisão de Brakka de acolhê-lo. @B (ato 2).',
  'Oferece o primeiro espaço para a apresentação de Glim e, apesar das reclamações, depois lhe dá comida escondido. Durante os Doze Dias tenta ordenar a fuga da trupe; Glim também o ouve chorando atrás da carroça. Essas cenas mostram sua função e cuidado, não um destino final. @B (atos 2–3).',
  'Últimas cenas recuperadas durante a desagregação do circo. Sobrevivência ou morte individual não narradas; não se deduz morte automática da destruição da trupe. @B',['B'],['Faccoes/Roda de Estopa','Personagens/Brakka Pedramansa','Personagens/Glim Sombrasselva'],[40],['Dornal Três Dedos'],['glim'])
N('Harlom Vinte-E-Dois','Mago da Roda de Estopa; dizia usar o número por sorte. Sua avaliação como acomodado e de repertório modesto vem da perspectiva de Brakka, não de ficha objetiva. @B (ato 2).',
  'Gosta do talento de Glim e o chama de ilusionista, mas empalidece ao ver uma página do grimório e evita lidar com ela. Durante os Doze Dias tenta produzir luz, teme atrair ameaças e a apaga. O temor do livro está documentado; o conhecimento exato que reconheceu não. @B (atos 2–3).',
  'Destino individual após a crise não narrado. Não há confirmação de que tenha morrido com a Roda de Estopa. @B',['B'],['Faccoes/Roda de Estopa','Personagens/Glim Sombrasselva','Itens/Grimorio de Glim'],[40],['Harlom'],['glim'])
N('Rumo','Integrante da Roda de Estopa associado à música: o background menciona sua música batendo em panela. Não há espécie, sobrenome ou biografia individual recuperados. @B (ato 2).',
  'Na crise dos Doze Dias, Glim o vê parar de falar e sentar-se contra uma árvore, olhando o vazio. A descrição registra abatimento no episódio; não estabelece morte ou condição sobrenatural permanente. @B (ato 3).',
  'Última cena conhecida no período da crise; destino posterior aberto. @B',['B'],['Faccoes/Roda de Estopa','Personagens/Miri','Eventos/Queda da Roda de Estopa'],[40],[],['glim'])
N('Miri','Pessoa da Roda de Estopa lembrada por suas piadas na rotina da trupe. A fonte não recupera espécie, função formal ou sobrenome. @B (ato 2).',
  'Integra a família de estrada que acolhe Glim, ao lado de Brakka, Dornal, Harlom e Rumo. Essa presença breve sustenta uma nota de vínculo, sem permitir inventar carreira ou relações além da trupe. @B (ato 2).',
  'Não há desfecho individual narrado após os Doze Dias Rubros. A perda da família de lona por Glim não comprova a morte de Miri. @B (ato 3).',['B'],['Faccoes/Roda de Estopa','Personagens/Rumo','Personagens/Glim Sombrasselva'],[40],[],['glim'])
N('Varo','Varo Cinzafrio, intermediário criminoso do período posterior aos Doze Dias Rubros. Observa o talento e os limites morais de Glim e passa a contratá-lo para distrações. @B (ato 4).',
  'Sua própria perspectiva revela que explora a distinção conveniente entre serviço pequeno e violência executada por terceiros. Paga pelos trabalhos de Glim e contorna seus escrúpulos. No percurso posterior, Glim relaciona essa rede ao Ébano; a afinidade mágica com o livro é interpretação do gnomo. @B (atos 4 e 6).\n\nTom é morto por um homem que acompanhava Glim em um serviço; a cena não nomeia o agressor como Varo nem documenta uma ordem sua. @B (ato 5).',
  'Posição formal no Ébano, paradeiro e sobrevivência atuais não estabelecidos. O vínculo criminal antigo não foi convertido em cargo de direção. @B',['B'],['Personagens/Glim Sombrasselva','Personagens/Tom do Cesto','Faccoes/Ebano'],[41],['Varo Cinzafrio'],['glim'])
N('Tom do Cesto','Tomas Rell, chamado Tom do Cesto, vendedor de frutas que acolhe Glim em gestos cotidianos e lhe dá maçãs. Seu ponto de vista narra a cena do serviço fatal. @B (ato 5).',
  'Reconhece Glim durante uma operação noturna perto do depósito e o chama de Magnífico. O homem que acompanha Glim reage com uma lâmina; Glim tenta protegê-lo sem conseguir. A narração não dá o nome do assassino e não o identifica diretamente como Varo. @B (ato 5).',
  'Morto na cena. Glim conserva uma moeda marcada por ele, e a morte o faz abandonar a dúvida conveniente sobre o submundo e investigar o Ébano. @B (ato 6).',['B'],['Personagens/Glim Sombrasselva','Personagens/Varo','Eventos/Trabalho de Glim para Varo','Itens/Memorias materiais de Glim'],[41],['Tomas Rell','Tom'],['glim'])
N('Nina','Humana da aldeia natal de Glim, criança quando ele voltou sem Lilo e adulta quando ele retorna anos depois. Glim a reconhece pelo rosto e pelas lembranças. @B (ato 6).',
  'Leva Glim à antiga casa e relata que seu pai morreu nos Doze Dias ao ir ao cemitério. Diz que sua mãe continua viva, incapacitada e cuidada por outras pessoas. Sua sugestão de que a mãe desejaria o retorno é esperança explicitamente incerta, não fala da própria mãe. @B (ato 6).',
  'Viva no reencontro narrado no background; paradeiro e idade atuais não fixados. É fonte de notícia familiar, sem parentesco inventado com Glim. @B',['B'],['Personagens/Glim Sombrasselva','Lugares/Aldeia natal de Glim'],[42],[],['glim'])

N('Tahen','Colega de estudos de Okay, da mesma escola e organização mãe de arquivistas ligados à sociedade élfica. Não há parentesco biológico indicado pela expressão irmãos de organização. @T24 (01:57:35; 02:20:24).',
  'Procura Okay após notícias do ataque a Eral e traz relatos de milagres, pesquisas e expedições desaparecidas. Diz que o antigo professor de Okay foi na segunda leva para o destino marítimo. Essas notícias são relatos trazidos pelo colega, não descoberta presencial dos Magníficos. @T24 (02:09:57–02:26:40), @H (Arquivistas).',
  'Visto na S24 como visitante e contato vivo. Destino posterior individual e notícias conclusivas das expedições não recuperados. @T24 @H',['T24','H'],['Personagens/Okay dBoa','Personagens/Elrohir','Faccoes/Arquivistas','Lugares/Covil maritimo'],[31],[],['glim'])
N('Elrohir','Elfo ligado à organização de arquivistas de Okay, segundo a síntese do handoff. Chega com outros elfos depois das notícias do ataque e da preocupação com a segurança do colega. @H (Arquivistas; Contatos religiosos e planares).',
  'É relacionado às pesquisas sobre aparições divinas e ausência de avatares autênticos desde a Noite Eterna. A hipótese de deuses impedidos de descer pertence ao pesquisador; não se converte em lei cosmológica confirmada. @H (Forças dos Magníficos e divindades; síntese da S25).',
  'Contato atual na fase S25; não há destino individual posterior recuperado. Nome do professor desaparecido e resultado das investigações continuam abertos. @H',['H'],['Personagens/Okay dBoa','Personagens/Tahen','Faccoes/Arquivistas'],[31,46],[],['glim'])
N('Aurel Vesperal','Visitante que se apresenta como Aurel Vesperal, de fala arcaica e aparência idêntica à de Carlos carpinteiro. A semelhança é afirmada pelo mestre; o jogador confirma posteriormente que o corpo era do carpinteiro. @T26 (00:19:01–00:20:17), @J',
  'Deseja o amuleto de Crave, participa da limpeza e passa a drenar vitalidade por toque e energia negativa. Reconhecer o Fogo Primordial e falar de Arkhavel são elementos do encontro, sem comprovar sua autobiografia. O comportamento e os poderes são descritos na síntese do handoff e na transcrição do combate. @H (Aurel Vesperal), @T26.\n\nApós a destruição do corpo, o sangue está coagulado e a mesa identifica Carlos. O grupo lembra anjos que caçavam um demônio possessor e um sobrenome semelhante; o mestre descreve a conclusão como crença deles. Lich foi hipótese de jogadores. Dois dias de estudos depois, um taverneiro entrega bebida com pedido semelhante, encomendada naquela manhã por uma mulher que não foi vista pelo grupo. @T26 (02:40:04–02:42:04; 02:45:55–02:47:36).',
  'Corpo usado no combate destruído e identificado como Carlos carpinteiro. Morte definitiva do possessor, identidade da mulher e ligação exata com os caçadores permanecem abertas; o pergaminho de anjo não foi consumido. @T26 @J',['T26','J','H'],['Personagens/Carlos carpinteiro','Personagens/Crave','Itens/Pergaminho do anjo','Eventos/Confronto com Vesperal'],[21,23],['Aurel','Vesperal'],['glim'])
N('Carlos carpinteiro','Carpinteiro humano, vizinho em frente à torre de Arkhavel, com esposa e dois filhos. É pessoa distinta do guarda Carlos e do Carlos da investigação onírica de Fash. O jogador confirmou que foi seu corpo o usado por Vesperal. @H (Eral), @J',
  'A síntese do handoff registra a família afetada pela magia viva e cenas posteriores de Carlos vivo trabalhando no celeiro e da contratação da esposa para cuidar de animais. Cleide aparece como improviso de Glim e não foi adotado como nome confirmado. @H (Eral; síntese de S4 e S9–S14).\n\nNa S26 Vesperal aparece com sua aparência; após o combate a mesa identifica o corpo como Carlos. A identificação específica como carpinteiro é confirmação posterior do jogador, não resultado nominal mais detalhado da transcrição. @T26 (00:19:01; 02:40:38), @J',
  'Morto até a S26, mas momento e circunstâncias da morte desconhecidos. A condição da esposa e dos filhos após as crises não foi resolvida. @J @H',['H','J','T26'],['Personagens/Aurel Vesperal','Personagens/Carlos guarda','Lugares/Casa de Carlos','Eventos/Caso Carlos e magia viva'],[21],['Carlos — carpinteiro'],['glim'])
N('Carlos guarda','Guarda humano de Eral, morto no arco anterior à crise do prefeito. Não é o carpinteiro cujo corpo aparece com Vesperal, nem o guarda Carlos do sonho da campanha antiga. @H (Eral), @J',
  'A síntese do handoff registra o cadáver levado à igreja e depois roubado no arco S8–S11. Em S13, Glim afirma a Tork que já sabiam que o prefeito havia matado Carlos; essa fala é uma acusação de personagem e não resolve sozinha cadeia de mando ou autoria material. @H @T13 (00:33:56).',
  'Morto; destino do corpo roubado e responsáveis não confirmados. Não atribuir o roubo a Firael por analogia com os casos investigados na S25. @H',['H','J','T13'],['Personagens/Carlos carpinteiro','Personagens/Prefeito humano de Eral','Personagens/Firael'],[22],['Carlos — guarda de Eral'],['glim'])
N('Silthan','Dono ou líder da arena de Eral, conforme a síntese do handoff. As funções de Silthan, do conde e da condessa e dos demais financiadores não foram reconciliadas num único organograma. @H (Arena), @T13 (00:54:32–00:55:18).',
  'Passa a pagar ao Mercado Negro por operação e cativos, sofre pressão do filho de Arkhavel e do falso prefeito e perde parte substancial dos ganhos. Seu irmão na capital é morto pelo Mercado como punição pelo uso indevido do nome da rede como proteção. A relação secreta do filho com o Aboleth era desconhecida dele. Esses fatos são síntese do handoff das cartas de S16. @H (Arena; Conclave).',
  'A arena cai, mas o destino pessoal de Silthan não foi individualizado com segurança nesta consulta. Não se declara sua morte apenas pela derrota dos chefes combatidos. @H',['H','T13'],['Faccoes/Arena de Silthan','Faccoes/Mercado Negro','Personagens/Filho de Arkhavel ligado ao prefeito','Eventos/Queda da arena'],[28],[],['glim'])
N('Teodoron Talent','Duque Teodoron Talent, responsável pela caravana que segue para Eral, sem estar pessoalmente nela. A impressão de que Eral pertence a seu domínio é de Glim no diário. @G (S1).',
  'A escolta leva uma mulher possuída e uma esmeralda para pagar Arkhavel. O grupo supõe parentesco da mulher com os Talent pelo aparato militar, sem confirmação. Depois da morte do prefeito e do ataque, Eral aguarda ajuda e novo prefeito; não há resposta pessoal do duque registrada nas passagens consultadas. @G (S1), @T18 (01:10:45).',
  'Sem encontro direto ou estado atual individual confirmado. Não recebeu título de rei nem se inferiu um reino chamado Talent. @G @H',['G','T18','H'],['Personagens/Mulher possuida da caravana','Personagens/Prefeito humano de Eral','Lugares/Eral'],[20,47],['Duque Teodoron Talent'],['glim'])
N('Kuat','Criatura identificada por Glim como Kuat abominação após perder o disfarce de mordomo da casa do prefeito. Kuat pode funcionar aqui como designação da criatura, não nome pessoal confirmado. @G (S12).',
  'Ataca com bola de fogo e mísseis, derruba vários companheiros e acaba desacordado por um golpe de Glim. O narrador o mantém inconsciente enquanto espera resgate. A associação geral com criação por Aboleths é conhecimento declarado de Glim; o dossiê de Okay, por sua vez, relata que a mesa o identifica como criação de Arkhavel e que Okay o cura para interrogatório. Essa informação derivada merece conciliação, não descarte nem autoridade automática. @G (S12), @OK (7.10).\n\nT16 explica que o prefeito humano era controlado por um filho de Arkhavel e que o Aboleth era parceiro secreto desse filho. A passagem não fornece nome pessoal inequívoco; a equivalência integral entre o rótulo Kuat e o filho permanece em pendência, sem fundir a nota a Donovan. @T16 (01:17:32–01:18:57).',
  'Glim o captura vivo em S12; o dossiê registra interrogatório posterior e entrega a Arkhavel. O relato de Glim em S13 de que a criatura morreu não fixa sozinho se sabia do interrogatório ou qual foi o desfecho. @G @OK @T13 (00:33:56).',['G','OK','T16','T13'],['Personagens/Filho de Arkhavel ligado ao prefeito','Personagens/Arkhavel','Personagens/Donovan','Personagens/Prefeito humano de Eral'],[16],[],['glim'])
N('Donovan','Filho de Arkhavel, conhecido e temido ou respeitado pelo Mercado Negro. É outro indivíduo além do filho que controlava a situação do prefeito de Eral. A distinção é explicitada na conversa da mesa. @T16 (01:17:32–01:18:57; 01:26:37–01:27:54).',
  'Seu nome aparece nas cartas para justificar a suposta irmandade dos Magníficos com os experimentos de Arkhavel. O mestre diz que poderia estar longe e que o nome do filho presente ainda não era conhecido. Uma avaliação de que os Magníficos fingem incompetência para atrair iscas é atribuída a Donovan nas cartas; não é prova de que o grupo realmente execute tal estratégia. @T16 (01:27:14; 01:30:51).',
  'Cargo, natureza da filiação, endereço e estado atual desconhecidos. Não foi fundido ao Kuat ou ao controlador do prefeito. @T16',['T16'],['Personagens/Arkhavel','Personagens/Filho de Arkhavel ligado ao prefeito','Faccoes/Mercado Negro'],[15,17],[],['glim'])
N('Filho de Arkhavel ligado ao prefeito','Filho de Arkhavel sem nome pessoal recuperado, chamado funcionalmente de prefeito nas cartas. O prefeito humano era outra pessoa, dominada; Donovan é outro filho conhecido pela rede. @T16 (01:17:32–01:18:57; 01:26:37–01:27:54).',
  'Controla a situação política e impõe associação à arena. Mantém parceria secreta com o Aboleth e esconde sua presença do pai. Nas cartas considera os Magníficos irmãos ou experimentos de Arkhavel e pretende abordá-los quando estiverem menos sob sua influência. Sua leitura de que o pai não se importa com filhos é juízo interessado. @T16 (01:17:32–01:18:57), @H (Arena).',
  'Nome, ligação exata com o mordomo Kuat e destino após o combate e interrogatório carecem de identificação precisa. As notas conservam referências cruzadas sem fundir os indivíduos por suposição. @G (S12), @OK (7.10), @T16',['T16','H','G','OK'],['Personagens/Kuat','Personagens/Donovan','Personagens/Arkhavel','Personagens/Prefeito humano de Eral'],[15,16],[],['glim'])
N('Prefeito humano de Eral','Prefeito humano de Eral, sem nome recuperado. T16 distingue o homem controlado do filho de Arkhavel que as cartas também chamam prefeito. Não se confunde com Donovan. @T16 (01:18:24).',
  'Na chegada do grupo à sala de jantar, continua comendo e não reage aos ataques. Crave o rasga com a corrente. A hipótese inicial do grupo é domínio por Aboleth ou Kuat; o esclarecimento posterior do mestre confirma que o humano estava controlado. Isso conserva a diferença entre a decisão dos personagens e a situação real que desconheciam. @G (S12), @T16 (01:18:24).',
  'Morto em S12. Guardas ainda anunciavam uma viagem com ele depois da morte, e Eral aguardava substituição após o ataque; a nomeação de sucessor não foi registrada. @G (S13), @T18 (01:10:45).',['T16','G','T18'],['Personagens/Filho de Arkhavel ligado ao prefeito','Personagens/Crave','Personagens/Teodoron Talent','Eventos/Crise do prefeito'],[16,47],[],['glim'])
N('Tauro','Minotauro em aparência, revelado como golem de carne criado por Arkhavel a partir dos restos de 32 ajudantes. Um item baseado em ajudantes específicos lhe dá forma e consciência. O exame de S2 sustenta a construção; não equivale a 32 pessoas plenamente recuperadas. @G (S2).',
  'Procura recuperar o braço arrancado, que se tornara uma mulher. Arkhavel se surpreende com o fenômeno e propõe fabricar outro braço com carne de humanoide. A mulher tem coração de warforged e existência própria, sem causa explicada. A síntese do handoff acrescenta as almas presas em Tauro e a investigação prometida pelo Lamassu. @G (S2), @H (Arkhavel e suas relações; contatos planares).\n\nDefende a torre contra Kenku e goblins. O grupo o encontra gravemente ferido, junto de pelo menos três Kenku e quatro goblins mortos e agarrado à jovem morta. Ao reconhecer os companheiros desmaia, recebendo cura. @T18 (01:16:42–01:17:51).',
  'Vivo ao ser socorrido depois do ataque, mas estado posterior e destino das almas não resolvidos nas fontes consultadas. A morte da mulher não foi transferida a Tauro. @T18 @H',['G','H','T18'],['Personagens/Arkhavel','Personagens/Mulher originada do braco','Lugares/Torre de Arkhavel'],[18,19],[],['glim'])
N('Mulher originada do braco','Mulher sem nome recuperado, surgida do braço de Tauro depois de sua separação. Ela própria insiste nessa origem; Arkhavel não consegue explicar por que o braço não voltou a simples carne de golem. O exame encontra coração de warforged que não poderia ser retirado sem matá-la. @G (S2).',
  'Acompanha Tauro, é examinada na torre e resiste ao desconforto do procedimento. A hipótese de regeneração ou mutação dos corpos usados é de Glim. Não há parentesco, identidade anterior ou equivalência com a mulher possuída da caravana demonstrados. @G (S1–S2).',
  'Morta na invasão da torre durante o ataque a Eral. A cena mostra Tauro abraçado à menina morta, gravemente ferido. Não há retorno ou ressurreição registrados nesta consulta. @T18 (01:17:17–01:17:51).',['G','T18'],['Personagens/Tauro','Personagens/Arkhavel','Personagens/Mulher possuida da caravana','Eventos/Ataque a Eral'],[19],[],['glim'])
N('Mulher possuida da caravana','Mulher sem nome recuperado, transportada sob escolta à torre de Arkhavel no início da campanha. Arkhavel diz que um ritual de invocação malfeito resultou em possessão demoníaca. @G (S1).',
  'Soldados levam a carroça coberta e pagam com grande esmeralda pelo atendimento. O grupo especula que deva pertencer à família Talent devido à escolta; o diário não confirma esse parentesco. É outra pessoa além da mulher originada do braço de Tauro. @G (S1–S2).',
  'Última situação conhecida é a entrega a Arkhavel para tratamento. Identidade, ritual, entidade possuidora e desfecho não recuperados. Não relacioná-la automaticamente a Vesperal. @G',['G'],['Personagens/Arkhavel','Personagens/Teodoron Talent','Personagens/Mulher originada do braco'],[20],[],['glim'])
N('Taverneira de Eral','Dona ou responsável pela taverna de Eral, sem nome confirmado. Contrata ajuda contra os dois homens-cabra e oferece pagamento maior se deixarem de voltar ou menor se brigarem fora. @G (S2).',
  'A síntese do handoff registra o churrasco e o apoio à cidade. Seu nome aparece funcionalmente entre os suspeitos de influência sobre os Magníficos nas cartas, o que não demonstra que fosse infiltrada. @H (Eral), @T16 (01:20:09).',
  'A morte na guerra é registrada no handoff como notícia privada recebida por Okay e depois Crave, sem comunicação registrada a Glim até S26. Não foi atribuído um nome a partir de brincadeiras ou falhas de transcrição. @H (Eral).',['G','H','T16'],['Lugares/Eral','Personagens/Glim Sombrasselva','Eventos/Ataque a Eral'],[24],[],['glim'])
N('Kenku caolho','Interlocutor Kenku que fornece informações e ajuda com planos ou armadilhas, segundo a síntese do handoff. As grafias Tausky, Talosky e Towski oscilam; não foram transformadas em três indivíduos nem em nome canônico certo. @H (Eral).',
  'Relaciona-se ao grupo dos Kenku primeiro auditores do Mercado e depois contratados por Silthan. As cartas suspeitam de um Kenku excessivamente próximo dos Magníficos; suspeita não é confirmação de infiltração benevolente. O ataque posterior demonstra traição coletiva e saque, mas não identifica cada agressor pelo nome. @H (Kenku), @T16 (01:21:42), @T18 (01:08:18–01:16:04).',
  'Paradeiro após o saque desconhecido. Os mortos Kenku na torre não permitem concluir que ele era um deles. A responsabilidade individual precisa de confirmação além da pertença ao grupo. @T18',['H','T16','T18'],['Faccoes/Kenku de Eral','Personagens/Silthan','Personagens/Tork'],[29],[],['glim'])
N('Gnoll sobrevivente','Gnoll sem nome confirmado, sobrevivente do confronto inicial com os Magníficos. A síntese do handoff registra que depois reconhece Glim e mostra uma cicatriz de flecha. @H (Eral; S21–S22).',
  'No primeiro caso o grupo descobre que eram quatro gnolls e um fugiu; Tork exigia prova para agir. O reaparecimento como adversário mais experiente pertence ao arco goblinoide posterior, sem justificar retroativamente toda suspeita sobre outras pessoas da espécie. @G (S3), @H',
  'Morto por Crave na S22, segundo a síntese do handoff. Não há nome ou relações familiares recuperados; o estado do indivíduo não deve ser confundido com o de todos os gnolls da região. @H',['H','G'],['Personagens/Crave','Personagens/Tork','Eventos/Crise dos refens'],[],[],['glim'])
N('Driade do cajado de girassol','Ser descrito como dríade semelhante a fada centaura, portadora de um cajado de grande girassol. A descrição e os efeitos vêm do relato dos pesquisadores na S25, resumido no handoff. Sua identidade própria não foi recuperada. @T25 (00:40:29), @H',
  'O cajado faz plantas florescerem e crescerem rapidamente e é associado à remoção de corrupção. O mestre depois explica que a planta convertida no artefato era o antigo personagem do druida; o jogador confirma o nome Timo. Isso vincula Timo à planta/cajado e conserva a dríade como portadora distinta. @T25 (01:51:24–01:51:56), @J @H',
  'Portadora do artefato no relato atual. Não se conhece nome, origem, paradeiro preciso ou relação voluntária com a consciência de Timo. Não é apresentada como reencarnação dele. @J @H',['T25','J','H'],['Personagens/Timo','Itens/Cajado de girassol','Lugares/Santuario da driade'],[5],['Dríade do cajado de girassol'])
N('Furion','Profeta e emissário da floresta, humanoide de traços arbóreos, conforme Personagens e Heróis. Essa fonte está marcada revisar_continuidade; a menção é preservada como proveniência, sem atestar automaticamente presença na campanha material. @PH',
  'A fonte o agrupa a personagens da história antiga, mas não recupera aqui cena de encontro, falas, missão ou destino. O ente sem nome citado no diário de Fash não foi identificado como Furion apenas por aparência vegetal semelhante. @PH @F (08/02).',
  'Continuidade e destino pessoal não verificados. A nota registra a evidência existente e a pergunta necessária, sem completar uma biografia por invenção. @PH',['PH','F'],['Personagens/Timo','Personagens/Silvanus'],[39])
N('Beholder da biblioteca','Beholder que Fash vê na grande biblioteca subterrânea durante o solo de cerca de 45 dias. Fash recua sem ser percebido; não há diálogo ou nome pessoal. @F (solo dos 45 dias).',
  'A biblioteca é acessível por uma trifurcação que também aponta para raças aracnídeas. A síntese do handoff dos mapas atuais o inclui no equilíbrio regional por tratado; possíveis interesses de Firael em seu cérebro são motivos especulados, não plano comprovado. @F @H (Antagonistas históricos; organização de Firael).',
  'Existência antiga observada e presença atual mediada pelos mapas e relatos. É distinto do beholder flamejante da provação de Glim. Não há encontro atual confirmado nesta consulta. @H',['F','H'],['Lugares/Biblioteca do beholder','Personagens/Firael'],[44])
N('Cerebro Anciao','Entidade ancestral aprisionada por quatro povos segundo o diário do Druida Sangrento. A quarta raça é apenas descrita como extraplanar. Não foram adotados nomes próprios ou títulos adicionais do documento Personagens e Heróis, marcado para revisão de continuidade. @F (15/01), @PH',
  'Oferece conhecimento por jogos cujo fracasso enfraquece as runas da prisão. O diário atribui parte da decadência dos povos ao uso interessado desse conhecimento. Firael acredita que jogar evitaria o fim do mundo; essa justificativa é alegação transmitida por ele, não garantia. Fash e Timo suspeitam de controle, mas a tentativa de proteção não demonstra mudança aparente. @F (10/01–18/01 e 08/02), @H (Povos antigos).\n\nNa morte de Rake, Firael está trancado com ele. Mais tarde acumula doze derrotas além do combinado. Timo havia vedado temporariamente o acesso com rochas. Na S25 o mestre confirma o Cérebro como chefe superior na organização atualmente liderada por Firael. @F (18/01–08/02), @T25 (01:35:35).',
  'Autoridade superior atual confirmada; condição material da prisão, corpo e eventual libertação não são descritos inequivocamente. Não se conclui a libertação apenas contando derrotas sem conhecer os efeitos exatos do selo. @T25 @F',['F','PH','H','T25'],['Personagens/Firael','Personagens/Druida Sangrento','Faccoes/Organizacao de Firael'],[8],['Cérebro Ancião'])
N('Cavaleiro da Morte','Cavaleiro da Morte referido por Timo e descrito pelo Necromante como aprisionado ou adormecido nas proximidades. Nome pessoal e local exato não recuperados. @F (solo dos 45 dias).',
  'O Necromante o considera ameaça à organização: ao despertar, mobilizaria mortos-vivos numa guerra caótica sem propósito. É previsão do NPC. O jogador depois cogita condicionalmente que possa ter despertado e tomado a necrópole; não afirma que ocorreu. @F @J',
  'Despertar, atuação e domínio atuais não confirmados. Não foi identificado com a área dos mortos-vivos imóveis da campanha de Glim ou com o Necromante. @J @H',['F','J','H'],['Personagens/Necromante','Lugares/Necropole','Lugares/Area dos mortos-vivos imoveis'],[34])
N('Mulher das memorias','Mulher sem nome recuperado, ligada a uma montanha e à restauração de lembranças mais antigas de Okay. Surge como pessoa lembrada da vida de Kael após a recuperação da S25. @T25 (01:37:18–01:38:10), @H (Contatos religiosos e planares).',
  'Okay lembra que poderia encontrá-la em um local combinado. O mestre responde que ele acha que estará lá e precisa verificar; isso não confirma sobrevivência ou permanência. A lembrança recuperada não devolve automaticamente as vidas anteriores às quais ela dava acesso. @T25',
  'Procura planejada, sem encontro atual registrado. Nome, natureza, condições para devolver memórias e paradeiro presentes continuam abertos. @T25 @H',['T25','H'],['Personagens/Okay dBoa','Personagens/Kael','Lugares/Montanha das memorias'],[4])
N('Chefe goblin','Chefe goblin sem nome recuperado, portador de condição chamada doença que invertia acertos e erros ao redor. A síntese do handoff distingue esse efeito de alterar livremente todos os resultados. @H (Chefe goblin, símbolos e entidade planar).',
  'Cura o fere, sem ser anulada pela inversão, e Okay o mata dessa forma. Fumaça negra e mudanças de idade do corpo ocorrem após a morte. Rabiscos da tenda e símbolos perfeitamente desenhados na caverna são ocorrências diferentes; a associação a uma entidade planar é interpretação, não identificação da causa. @H (síntese da S21).',
  'Morto; corpo envelhece ou rejuvenesce e termina em pó no relato. Origem da doença, identidade da possível entidade e alcance da ligação com as inscrições continuam abertos. @H',['H'],['Personagens/Okay dBoa','Lugares/Assentamento goblinoide'],[45],[],['glim'])

N('Kord','Divindade ligada ao amuleto de Crave e à igreja de Tólomon e Tariun. A nota registra as relações e ensinamentos documentados na campanha, sem importar cosmologia externa. @G (S17), @T23',
  'Tólomon conta que Kord usava o artefato entre mortais e sugere que Rudiger fosse uma forma do deus. Tariun ensina força para proteção, desafio e competição. Na prova da neve, a figura do prelúdio de Crave recolhe vivo o sacerdote abandonado e demonstra decepção; isso não resolve por si a classificação de avatar. @G (S17), @T23 (00:08:51–00:16:58; 03:46:30).\n\nO rito do cinto e a relação com o amuleto são episódios distintos. Pesquisadores afirmam não haver avatares autênticos desde a Noite Eterna, segundo a síntese do handoff; sonhos e manifestações privadas exigem qualificação em vez de harmonização automática. @H (Forças dos Magníficos e divindades).',
  'Relação ativa com o arco de Crave documentada; estado da redenção e natureza exata do mentor não concluídos. A aparência de uma figura em provação não autoriza identificá-la sem reserva como o deus materialmente presente. @H @T23',['G','T23','H'],['Personagens/Crave','Personagens/Rudiger','Personagens/Tariun','Personagens/Tolomon','Itens/Amuleto de Kord'],[12,13,46],[],['glim'])
N('Hextor','Divindade identificada na mesa como deus da força e da guerra e inimigo direto de Kord. Extor e variantes aparecem na transcrição, aqui subordinadas à identificação usada no handoff. @T23 (00:26:22–00:26:47), @H',
  'Um emissário oferece livro e força a Crave, reinterpretando sua culpa e a perda de favores como punição injusta. A oferta e os argumentos são propaganda do emissário, não confirmação de que seu deus concederia tudo sem custo. Crave recusa. @H (Igreja de Kord; síntese da S23).',
  'Não há aparição direta confirmada do próprio Hextor nas passagens consultadas. O emissário não foi fundido ao deus e o livro recusado conserva seu papel específico. @H',['T23','H'],['Personagens/Kord','Personagens/Crave','Itens/Livro de Hextor'],[12],['Extor'],['glim'])
N('Silvanus','Divindade à qual a comunidade da floresta associa a escolha de Timo na campanha antiga. O diário de Fash registra a homenagem e admite não saber o alcance da escolha. @F (08/02).',
  'Depois da morte de Rake e do retorno de Timo com traços ferais, fadas, ninfa, ente e outras criaturas trazem presentes e pedem ajuda com zumbis e animais em transe. Isso sustenta o vínculo religioso, mas não demonstra que toda transformação posterior de Timo tenha mecanismo conhecido. @F (25/01 e 08/02).',
  'O destino de Timo como planta/cajado é confirmado posteriormente; a natureza da intervenção de Silvanus, o título de rei e a continuidade da vontade do druida não foram resolvidos só pela homenagem. Títulos adicionais em Personagens e Heróis dependem de revisão. @J @PH',['F','J','PH'],['Personagens/Timo','Personagens/Rake','Personagens/Furion'],[5,39])
N('Lolth','Divindade mencionada na história da guerra drow, na maldição do Druida Sangrento e nas estátuas que os anões escravizados eram obrigados a produzir. A evidência é interna ao diário e aos relatos que ele transcreve. @F (15/01, 18/01 e 25/01).',
  'O diário do drow atribui ao pacto com Lolth o fim das duas civilizações e sua obrigação de guardar o Cérebro. Fash espera que a falha seja punida pela transformação em drider e pela humilhação diante de uma amante, mas a primeira é inferência dele e a história da amante depois se revela manipulação do drow. @F (15/01 e 18/01).',
  'Não há intervenção atual direta ou transformação em drider confirmada nesta consulta. A libertação dos anões e a quebra de estátuas não autorizam concluir o estado presente da divindade. @F (25/01).',['F'],['Personagens/Druida Sangrento','Personagens/Cerebro Anciao','Personagens/Anao guardiao'],[],[],['fash'])
N('Pelor','Nome de divindade sugerido por Tólomon para explicar a luz de Ryld. O diário qualifica a associação como possibilidade pela luz, não identificação comprovada. @G (S17).',
  'A luz de Ryld reage ao fogo de Okay na caravana, junto às sombras de Glim e à pressão de Crave. O fenômeno experimentado pelos quatro é distinguível da explicação religiosa posterior. Nenhum desses efeitos comprova sozinho patronato de Pelor. @G (S1 e S17).',
  'Ligação com Ryld permanece hipótese de NPC. Não há biografia, intervenção direta ou culto local específico confirmado nas fontes consultadas para esta nota. @G',['G'],['Personagens/Ryld','Personagens/Tolomon','Personagens/Okay dBoa'],[14,46],[],['glim'])

N('Vyrix','Dragão de cristal jovem, de nome com grafia ainda provisória, encontrado na região da expedição dos rangers. A identidade e ações desta nota vêm da síntese do handoff da S17. @H (Eral, floresta e contatos atuais).',
  'Conhece Folha-Seca, fornece bestas aos rangers, auxilia a orientação dos Magníficos e mantém seu covil em segredo. O mestre corrige seu sopro para luz capaz de cegar, não gelo; a aparência cristalina não deve substituir essa correção. @H (síntese da S17).',
  'Sem morte registrada ou paradeiro posterior confirmado. Seu contato com rangers não o torna automaticamente responsável pelos crimes da arena ou pelo desaparecimento da expedição. @H',['H'],['Personagens/Folha-Seca','Eventos/Busca dos rangers'],[43],[],['glim'])

assert len(cadastro)==68, len(cadastro)
faltam=sorted(set(cadastro)-{x['destino'] for x in notas})
assert not faltam, faltam
manifesto={
  'dominio':'personagens','atualizado':'2026-10-29','estado':'congelado',
  'cobertura':{'cadastrados':len(cadastro),'cobertos':len(notas),'faltantes':faltam},
  'notas':notas,'pendencias':perguntas,'extras':[],
  'fontes_realmente_consultadas':[
    {'destino':FONTES[x], 'alcance':a} for x,a in [
      ('H','Leitura do handoff, com seções de correções, história antiga, pessoas, magia e mistérios; algumas notas curtas dependem somente desta síntese e dizem isso.'),
      ('J','Texto integral dos esclarecimentos do jogador de 23/10/2026.'),
      ('F','Passagens da abertura/Dia 45 e solo dos 45 dias; 08/02 a 10/01; 01/12, solo 02/12, 28/11, 07/11, 31/10 e 25/10; busca textual seletiva de nomes e datas.'),
      ('B','Ato 1 e acolhimento do ato 2; passagens de Harlom, Rumo/Miri, crise e perda de Brakka, Varo, morte de Tom e retorno à aldeia; busca textual para nomes e destinos.'),
      ('G','Passagens S1–S3 de caravana, contrato, Tauro e mulher; S11/S12–S13 sobre prefeito/Kuat; trecho S17 de Tólomon, amuleto e Rudiger; buscas textuais seletivas.'),
      ('OK','Identidade/ascendência e início familiar; 7.10 sobre Kuat e interrogatório. Dossiê tratado como fonte derivada e interpretação a revisar.'),
      ('PH','Texto integral; marcado revisar_continuidade. Furion é atestado apenas como menção dessa fonte; nomes próprios adicionais não foram promovidos.'),
      ('TIM','Introdução, personagens e passagens recuperadas por busca sobre Timo Pé-de-Musgo, Fesh, datas e arcos. Fonte derivada não reconciliada.'),
      ('FA','Texto integral da nota de background de Fash/Tinkar no vault, em revisão de continuidade.'),
      ('T13','Passagens sobre Tork, represálias, emboscadas, relato da morte do prefeito/Kuat e financiadores da arena; busca seletiva.'),
      ('T16','Passagens 00:34 e 01:17–01:30 sobre ausência de Arkhavel, filhos, cartas, Ébano e avaliações; busca seletiva.'),
      ('T18','Passagens 01:08–01:18: ataque, Tork, clérigos, ausência de rangers, mensagem Kenku, Tauro e menina morta.'),
      ('T20','Passagens 00:08–00:15: retorno de Ryld, contratos planares e escaravelhos.'),
      ('T21','Passagens recuperadas por pesquisa sobre símbolos, runa e memória juvenil; não leitura integral.'),
      ('T23','Recapitulação 00:07–00:17, identificação de Hextor e 03:46–03:47 da figura que recolhe o sacerdote; pesquisa seletiva.'),
      ('T24','Passagens 01:57–02:26 sobre Tahen e professor desaparecido; 03:03–03:05 sobre manifestação e função do familiar; busca seletiva de sombras.'),
      ('T25','Passagens 00:40 do cajado, 01:34–01:40 da memória/mortes/Firael/Cérebro, 01:49–01:56 das motivações e Timo/cajado, 02:19–02:21 do roubo ao dragão, atualização do familiar e ausência de Arkhavel; busca seletiva.'),
      ('T26','Passagens 00:19–00:20 do nome e semelhança de Carlos, 02:39–02:48 de corpo/mesa/hidromel e encerramento; busca seletiva de Vesperal/Carlos.')]],
  'limites':[
    'Não houve leitura integral de todas as transcrições ou do diário de Glim. Cada síntese não reaberta é identificada como proveniente do handoff.',
    'Não foram consultados documentos externos nem lore de D&D; links remotos preservados nas fontes não foram abertos.',
    'Tareksin, pais de Glim, anjos, emissário de Hextor, Lamassu e personagens do sonho podem merecer notas próprias futuras; nesta etapa suas informações ficam nos vínculos e nas fontes, sem extras não coordenados.',
    'Fesh, nomes expandidos de Hourian e do Cérebro, família Velkyn e nomes de organizações presentes em documentos revisar_continuidade não receberam aliases canônicos.',
    'A sobrevivência individual de participantes do circo, rangers, Tólomon e Kenku caolho não foi deduzida de destinos coletivos.',
    'Nenhum arquivo de fontes, sessões, anexos, índices ou cadastro comum foi alterado por este script.'
  ],
  'escritas':['conteudo/'+x['arquivo'] for x in notas]+['conteudo/'+x['destino']+'.md' for x in perguntas]+['docs/enciclopedia/personagens.json','tools/consolidar_personagens.py']
}
manifest_path=ROOT/'docs/enciclopedia/personagens.json'
if manifest_path.exists():
    # O núcleo pode ser regenerado sem apagar do manifesto o complemento nominal.
    anterior=json.loads(manifest_path.read_text(encoding='utf-8'))
    extras_preservados=anterior.get('extras',[])
    if extras_preservados:
        manifesto['extras']=extras_preservados
        manifesto['notas']+=extras_preservados
        manifesto['cobertura'].update(extras=len(extras_preservados),total_notas=len(manifesto['notas']))
        manifesto['escritas']+=['conteudo/'+n['arquivo'] for n in extras_preservados]
        manifesto['limites']=[x for x in manifesto['limites'] if not x.startswith('Tareksin, pais de Glim')]
        manifesto['limites'] += [x for x in anterior['limites'] if x.startswith('O complemento nominal')]
        alcance_ant={x['destino']:x['alcance'] for x in anterior['fontes_realmente_consultadas']}
        for f in manifesto['fontes_realmente_consultadas']:
            if f['destino'] in alcance_ant and 'Complemento:' in alcance_ant[f['destino']]:
                f['alcance']=alcance_ant[f['destino']]
manifest_path.write_text(json.dumps(manifesto,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(json.dumps({'notas':len(notas),'pendencias':len(perguntas),'faltantes':faltam},ensure_ascii=False))
